export const NEW_AGE_AMBIENT_EVENTS = [
  {"min": 1, "max": 1, "text": "Đang được bà nội bế nựng mớm bột cháo ngon lành, mày bất ngờ vận nội công thả một quả rắm sinh học, kèm theo bãi mìn màu vàng mù tạt ướt nhẹp thấm qua bỉm dính thẳng vào áo lụa của bà. Kết quả bà khóc thét, ông bô mày phải thức giặt đồ đến 12h đêm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-01"},
  {"min": 1, "max": 1, "text": "Nằm chơi trên sàn nhà, mày vô tình nhặt được một con gián đất đang ngắc ngoải. Với bản năng sinh tồn hoang dã, mày đưa thẳng vào miệng nhai rôm rốp. Mẹ mày phát hiện ra móc họng không kịp, báo hại cả nhà đưa đi viện rửa ruột.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-02"},
  {"min": 1, "max": 1, "text": "Lần đầu tiên mọc răng ngứa lợi, mày thấy ti bố đang cởi trần nằm ngủ ngáy pho pho. Mày bò lại gần và cắn ngập răng vào núm vú ông bô. Tiếng hét thất thanh vang vọng cả khu phố lúc 2 giờ sáng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-03"},
  {"min": 1, "max": 1, "text": "Bắt đầu tập nói, thay vì gọi \"Ba, Mẹ\" như con người ta, từ đầu tiên mày thốt ra lại là một từ chửi thề do nghe trộm được ông chú hàng xóm chửi chó. Cả họ hàng sang chơi im bặt, bố mẹ mày chỉ biết đội quần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-04"},
  {"min": 1, "max": 1, "text": "Mày bị bắt quả tang đang bốc nước từ bồn cầu bôi lên mặt với nụ cười mãn nguyện. Mùi hương ngây ngất đó khiến mẹ mày phải dùng nửa chai sữa tắm mới kì cọ sạch được.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-05"},
  {"min": 1, "max": 1, "text": "Lần đầu được cho đi tắm biển, mày tưởng cát là một loại bột ngũ cốc mới nên vã ngay hai vốc đầy vào mồm. Kết quả là mày ỉa ra cát suốt 3 ngày liền, đít xước như giấy nhám.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-06"},
  {"min": 1, "max": 1, "text": "Chó nhà nuôi đang ăn cơm, mày lẫm chẫm đi tới giật đuôi nó. Con chó quay lại gầm gừ, thay vì sợ, mày tát thẳng vào mặt nó một cú lật hàm. Con chó trầm cảm bỏ ăn 2 ngày.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-07"},
  {"min": 1, "max": 1, "text": "Đêm khuya thanh vắng, mày tỉnh dậy nhưng đéo khóc, cứ ngồi nhìn chằm chằm vào góc tường tối thui rồi cười khanh khách. Bố mẹ mày sợ xanh mắt mèo, hôm sau phải mời thầy về cúng giải hạn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-08"},
  {"min": 1, "max": 1, "text": "Đang trườn trên giường, mày trớ ra một bãi sữa chua loét. Thay vì khóc gọi mẹ, mày tò mò lấy tay trát đều bãi trớ ra khắp mặt gối rồi nằm lăn lê bò toài lên đó như đang đắp mặt nạ spa.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-09"},
  {"min": 1, "max": 1, "text": "Được bú bình nhưng mày đéo bú, mày dùng cái bình sữa đập liên tục vào mặt ông anh trai đang nằm cạnh đến mức ổng chảy máu mũi khóc thét lên, từ đó ổng hận mày đến năm 18 tuổi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-10"},
  {"min": 1, "max": 1, "text": "Bò vào gầm giường, mày phát hiện ra cái bẫy chuột có sẵn miếng thịt nướng. Mày nhanh tay giật lấy nhai ngấu nghiến trước khi cái bẫy sập xuống. Mẹ mày lôi ra đánh một trận nhừ tử vì tội ăn tranh đồ của chuột.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-11"},
  {"min": 1, "max": 1, "text": "Đang ngồi xe đẩy dạo công viên, thấy con bồ câu bay qua ỉa bậy một bãi trắng xóa rơi bộp xuống đùi. Mày vội lấy ngón tay quệt cho vào mồm nếm thử vì tưởng là kem sữa.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-12"},
  {"min": 1, "max": 1, "text": "Chơi trò trốn tìm kiểu trẻ trâu, mày chui mẹ vào máy giặt cửa ngang nằm ngủ ngon lành. Cả nhà hú hồn tìm 2 tiếng đồng hồ, suýt báo công an bắt cóc.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-13"},
  {"min": 1, "max": 1, "text": "Lần đầu nhìn thấy cái quạt cây đang quay vù vù, tò mò mày thò ngay ngón tay út vào lồng quạt. Máu me túa lúa, cả xóm được một phen nghe ca nhạc thính phòng bằng tiếng khóc của mày.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-14"},
  {"min": 1, "max": 1, "text": "Mày lẫm chẫm tập đi, vịn ngay vào cái khăn trải bàn ăn. Kéo tuột một phát, bát canh cua nóng hổi úp trọn lên đầu con chó nhà. Mày an toàn nhưng con chó thù mày ra mặt.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-15"},
  {"min": 1, "max": 1, "text": "Bị muỗi đốt sưng cục to đùng trên trán, mày lấy tay gãi xước cả da rồi bôi cứt mũi vào để \"sát trùng\" theo bản năng. Trán nhiễm trùng sưng to như La Hán.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-16"},
  {"min": 1, "max": 1, "text": "Nằm trong nôi tập uống nước, mày hắt hơi một phát làm đổ sạch bình sữa vào gối. Mày nằm giữa bãi chiến trường trắng xóa rồi vẫn lăn ra ngủ như chưa có gì.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-17"},
  {"min": 1, "max": 1, "text": "Thấy ông nội làm rơi hàm răng giả vào cốc nước, mày lẻn ra thò tay vớt lên định đeo thử vào mồm mình. Vừa cho vào thì hóc, khóc ré lên làm ông nội tỉnh giấc suýt lên máu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-18"},
  {"min": 1, "max": 1, "text": "Mày trốn trong góc tối cắn nát 3 cục xà bông hỏa tốc của mẹ vì tưởng là thạch rau câu. Chiều hôm đấy mày ợ ra toàn bọt xà phòng như con cua đồng sắp chết.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-19"},
  {"min": 1, "max": 1, "text": "Được đi dự tiệc sinh nhật con nhà bác, mày bò ra giữa thảm phòng khách, ưỡn người rặn ra một cục cứt cứng ngắc to bằng quả chanh. Bữa tiệc giải tán sớm trong không khí nồng nàn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-01-20"},
  {"min": 2, "max": 2, "text": "Lợi dụng lúc bố đi đái, mày cầm chiếc điện thoại Nokia xịn xò của ông bô thả tõm vào xô nước lau nhà rồi đứng vỗ tay. Bố mày ra thấy cảnh tượng đó suýt thì lên cơn nhồi máu cơ tim.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-01"},
  {"min": 2, "max": 2, "text": "Mẹ mua cho bộ xếp hình xịn. Mày không xếp mà nhét thẳng một cục lego hình chữ nhật vào lỗ mũi. Cả nhà xúm lại dùng nhíp gắp mãi đéo ra, phải lên trạm xá nhờ bác sĩ thọc kìm vào lôi ra, máu me bê bết.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-02"},
  {"min": 2, "max": 2, "text": "Đang cởi truồng chạy lông nhông trong nhà thì có khách của bố đến chơi. Mày chạy thẳng ra phòng khách, đứng chống nạnh chĩa \"chim\" vào mặt khách cười ha hả. Bố mày ngượng chín mặt, vội lấy cái rổ úp vào.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-03"},
  {"min": 2, "max": 2, "text": "Thấy lọ phấn rôm của mẹ để trên bàn, mày với lấy rồi rắc trắng xóa khắp từ giường ra đến phòng khách. Mày tự bôi trắng bệch mặt mũi như cương thi, mẹ mày về nhìn thấy suýt ngất xỉu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-04"},
  {"min": 2, "max": 2, "text": "Đi ăn cỗ cưới cùng gia đình, trong lúc mọi người đang nâng ly dô dô, mày thò tay bốc thẳng nắm xôi gấc chọi thẳng vào mặt cô dâu. Đám cưới suýt thành đám tang vì hai họ xô xát.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-05"},
  {"min": 2, "max": 2, "text": "Học được trò nhổ nước bọt, mày ra đứng ngoài ban công nhổ phì phì xuống dưới đường. Đúng lúc bà tổ trưởng dân phố đi ngang qua, lãnh trọn bãi nước bọt vào đỉnh đầu. Bố mẹ mày phải mang giỏ hoa quả sang xin lỗi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-06"},
  {"min": 2, "max": 2, "text": "Mày phát hiện ra trò cắm đũa vào ổ điện rất vui. May là cầu dao tự ngắt, mày chỉ bị giật tung người cháy xém một nhúm tóc. Từ đó mày nhìn thấy ổ điện là sợ đái ra quần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-07"},
  {"min": 2, "max": 2, "text": "Trốn vào góc tủ quần áo ị đùn, sợ bị đánh nên mày cởi quần ra rồi dùng quần áo lụa của mẹ để chùi đít. Bãi chiến trường được ủ 3 ngày sau bốc mùi nồng nặc mới bị phát hiện. Trận đòn roi mây nhớ đời.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-08"},
  {"min": 2, "max": 2, "text": "Thấy cái ớt hiểm màu đỏ đẹp quá rơi dưới đất, mày nhặt lên nhai nhóp nhép. Hai giây sau mày khóc rống lên, nước dãi chảy ròng ròng, mồm sưng vều như mỏ vịt suốt cả tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-09"},
  {"min": 2, "max": 2, "text": "Đi siêu thị, mày lăn đùng ra sàn giãy đành đạch ăn vạ đòi mua ô tô đồ chơi. Mẹ mày quê quá bỏ đi luôn. Mày nằm bơ vơ giữa siêu thị 5 phút đéo thấy ai dỗ, lồm cồm bò dậy chạy theo khóc mếu máo.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-10"},
  {"min": 2, "max": 2, "text": "Bố vừa rửa sạch con xe máy dựng sân, mày ra nhặt hòn gạch ba banh khắc lên cửa xe mấy đường giun dế uốn lượn. Xót của, bố xách mày lên nện cho nát đít.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-11"},
  {"min": 2, "max": 2, "text": "Ngứa tay vặn núm bếp ga tanh tách chơi, mày suýt làm nổ mẹ cả bình ga. May mùi ga bốc lên nồng nặc mẹ mày phát hiện khóa lại, từ đó mày bị cấm túc vào bếp vĩnh viễn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-12"},
  {"min": 2, "max": 2, "text": "Bực tức vì con gà trống gáy ồn, mày cầm gậy lùa nó khắp vườn. Bị nó quay lại mổ cho phát giữa trán, mày khóc thét bỏ chạy vấp mẹ vào bãi cứt gà tươi, nhục nhã ê chề.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-13"},
  {"min": 2, "max": 2, "text": "Xem tivi thấy siêu nhân nhảy dù, mày xé mẹ quyển sổ đỏ của bố để gấp máy bay phi ra ngoài cửa sổ. Cả nhà phải lùng sục ngoài cống rãnh tìm lại mảnh giấy bạc tỷ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-14"},
  {"min": 2, "max": 2, "text": "Lẻn vào nhà tắm nghịch chai dầu gội Romano của bố, vắt kiệt cả chai ra sàn làm đường trượt tuyết. Mày trượt ngã đập mỏ vào bồn cầu, gãy cmn nửa cái răng sữa mới nhú.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-15"},
  {"min": 2, "max": 2, "text": "Thấy mâm cơm mẹ úp lồng bàn, mày mò vào bốc miếng thịt kho tàu nhai chán rồi nhả mẹ lại vào mâm. Chiều cả nhà ăn mâm cơm đầy nước dãi của mày mà không ai biết.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-16"},
  {"min": 2, "max": 2, "text": "Cầm bút bi đen của bố vẽ chi chít lên mặt bức ảnh thờ của cụ cố. Bố mày nhìn thấy quỳ lạy xin lỗi cụ rối rít rồi tiện tay lôi mày ra cho 5 chổi lông gà.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-17"},
  {"min": 2, "max": 2, "text": "Trèo lên bàn bắt chước ông nội uống trà. Rót nhầm phích nước sôi, mày bị phỏng tay khóc điếc tai cả xóm, bôi cả tuýp thuốc mỡ 1 tháng mới hết sẹo.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-18"},
  {"min": 2, "max": 2, "text": "Nuốt chửng 1 hòn bi ve vào mồm. Cả nhà tái mét dốc ngược mày lên đập lưng bồm bộp, mửa ra cả đống cháo lúc sáng nhưng hòn bi thì đến tuần sau mới ỉa ra được.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-19"},
  {"min": 2, "max": 2, "text": "Nửa đêm dậy đái, mày ngủ gật đái mẹ vào thùng gạo. Mẹ mày phải vo gạo kĩ x3 lần suốt cả tuần đó, ai ăn cơm cũng khen dạo này cơm có vị đậm đà.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-02-20"},
  {"min": 3, "max": 3, "text": "Ngày đầu tiên đi nhà trẻ, mày bị cướp đồ chơi. Không nói nhiều, mày lao vào cắn thẳng vào bắp tay thằng kia một vết răng rướm máu. Phụ huynh hai bên lên văn phòng hiệu trưởng mắng vốn nhau ỏm tỏi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-01"},
  {"min": 3, "max": 3, "text": "Trong giờ ngủ trưa ở lớp mầm non, mày đéo ngủ mà đi móc cứt mũi bôi lên tóc con bé nằm cạnh. Con bé tỉnh dậy khóc ré lên, cô giáo phạt mày ra góc lớp đứng úp mặt vào tường xơi nước.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-02"},
  {"min": 3, "max": 3, "text": "Chơi trò bác sĩ với mấy đứa trong xóm, mày lấy lá dâm bụt giã nát rồi ép thằng hàng xóm uống để \"chữa bệnh\". Thằng bé Tào Tháo rượt 2 ngày, phụ huynh nó vác chổi sang tận nhà chửi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-03"},
  {"min": 3, "max": 3, "text": "Cô giáo đang quay mặt viết bảng, mày ở dưới tụt quần đái thẳng vào chai nước Lavie của thằng lớp trưởng. Lúc nó uống vào nhăn mặt khen nước nay mặn thế, mày ngồi cười rung rốn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-04"},
  {"min": 3, "max": 3, "text": "Thấy bà nội cất bộ răng giả trong cốc, mày lấy ra đeo vào mồm rồi chạy ra đầu ngõ nhe răng dọa mấy con chó cỏ. Chó sợ sủa ầm ĩ, bà nội thì tìm răng vã cả mồ hôi hột.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-05"},
  {"min": 3, "max": 3, "text": "Tham gia hội thi bé khỏe bé ngoan, đến tiết mục múa, mày đéo múa mà đứng ngoáy mông rồi giơ ngón giữa (học từ ông anh) về phía ban giám khảo. Bố mày ngượng quá phải lao lên bế mày xuống gấp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-06"},
  {"min": 3, "max": 3, "text": "Cầm cây búa đồ chơi bằng nhựa gõ boong boong vào đầu ông nội đang ngủ trưa. Lực hơi mạnh tay, ông nội sưng một cục to bằng quả ổi, cấm tiệt mày không được bước chân vào phòng 1 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-07"},
  {"min": 3, "max": 3, "text": "Ở lớp mầm, đến giờ ăn xế, mày lén nhét con sâu tai trộm được ngoài vườn vào bát cháo của cô giáo thực tập. Cô giáo khóc thét bỏ chạy, mày được phong làm đại ca của lớp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-08"},
  {"min": 3, "max": 3, "text": "Mày gạ thằng bạn thi xem ai hét tiếng vịt kêu to hơn. Cả hai đứng gào ở ban công đến khi cô giáo chạy lên bắt đứng phạt vì làm cả trường tưởng có đàn vịt xổng chuồng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-09"},
  {"min": 3, "max": 3, "text": "Mẹ mới mua thỏi son MAC đỏ chót, mày lấy ra tô kín cái bệ xí bệt thành một cái mồm khổng lồ đẫm máu. Mẹ tiếc của khóc 3 ngày, mày ăn 3 cái bạt tai nổ đom đóm mắt.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-10"},
  {"min": 3, "max": 3, "text": "Bực mình vì mẹ không mua bim bim, mày lấy kéo cắt trọc mẹ lông con mèo cưng của nhà. Con mèo từ đó nhìn mày với ánh mắt hình viên đạn, hễ cứ đến gần là nó cào cho toạc da.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-11"},
  {"min": 3, "max": 3, "text": "Đang ngồi xem siêu nhân Gao, buồn ỉa quá nhưng lười đi toilet. Mày rặn luôn một cục tại chỗ, rồi lấy cái gối sô-pha đè lên giấu nhẹm đi. Tối bố mày đi làm về mệt ngả lưng xuống gối, ôi thôi một trải nghiệm nhớ đời.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-12"},
  {"min": 3, "max": 3, "text": "Sang nhà hàng xóm chơi, mày ngứa tay tháo mẹ van xe đạp điện của ông tổ trưởng dân phố. Sáng hôm sau ổng dắt xe đi làm muộn chửi bới um sùm cả ngõ, mày núp sau rèm cửa cười khúc khích.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-13"},
  {"min": 3, "max": 3, "text": "Chơi đất nặn ở trường, mày nặn một hình thù cực kỳ giống cục cứt, phết thêm tí nước cho bóng rồi đặt lên bàn cô giáo. Cô giáo tưởng thật tí thì nôn mửa, gọi phụ huynh lên mắng vốn ngay lập tức.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-14"},
  {"min": 3, "max": 3, "text": "Lần đầu được uống Sting dâu, mày bị tăng động cởi phăng áo chạy 10 vòng quanh sân khu tập thể, vừa chạy vừa gào thét như Tarzan gọi bầy.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-15"},
  {"min": 3, "max": 3, "text": "Thấy mâm ngũ quả ngày Tết, mày trèo lên bàn thờ trộm ngay quả thanh long nhai ngoạm một miếng to rồi lén đặt lại chỗ cũ. Mùng 1 Tết cả họ thắp hương với quả thanh long nham nhở dấu răng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-16"},
  {"min": 3, "max": 3, "text": "Bố đang tiếp khách sếp lớn ở nhà, mày lững thững đi ra từ phòng tắm, người ướt nhẹp cởi truồng 100%, tự tin giật cái đùi gà trên mâm nhai nhóp nhép. Sếp cười sặc sụa, bố mày thì muốn đào lỗ chui xuống đất.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-17"},
  {"min": 3, "max": 3, "text": "Cô giáo dặn mang hoa đến tặng nhân ngày 20/11, mày đéo có tiền nên vặt trộm bó hoa cúc vạn thọ trên mộ ông hàng xóm đem lên tặng cô. Bị phát hiện, mày phải quỳ xin lỗi trước bia mộ 3 tiếng đồng hồ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-18"},
  {"min": 3, "max": 3, "text": "Mày học được câu chửi thề cực gắt từ phim giang hồ mạng. Gặp ai đến nhà mày cũng chắp tay chào: \"Cháu chào bác địt con mẹ bác ạ!\". Bố mày phải tát gãy cmn cái chổi quét nhà vì tội láo toét.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-19"},
  {"min": 3, "max": 3, "text": "Mày bị táo bón 3 ngày, lúc đi ỉa rặn đỏ cả mặt. Đau quá, mày lấy cái đũa chọc vào lỗ đít để... khều cứt ra. Kết cục xước cả hậu môn, phải bôi thuốc mỡ rát kinh hồn suốt 2 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-03-20"},
  {"min": 4, "max": 4, "text": "Đang chơi trò bắn súng phốc bằng tre, mày nhắm ngay khe đít con chó cỏ của bà hàng xóm bóp cò. Quả đạn giấy nhai ướt sũng găm trúng hồng tâm, con chó rú lên chạy mất dạng 3 ngày không dám về nhà.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-01"},
  {"min": 4, "max": 4, "text": "Thấy bố giấu quỹ đen 500k trong cuốn từ điển. Mày lấy tờ tiền ra, tự hào lấy bút lông vẽ thêm râu ria, mắt kính cho Bác Hồ rồi để lại chỗ cũ. Bố mày lúc lấy tiền đi nhậu mở ra xem tí thì đột quỵ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-02"},
  {"min": 4, "max": 4, "text": "Ở lớp chồi, mày gạ gẫm con bé xinh nhất lớp ăn chung cái kẹo mút mày vừa nhai dở. Nó không chịu, mày cầm cả cái kẹo đính đầy cát dưới đất nhét thẳng vào mồm nó. Cô giáo gọi điện về bắt bố mẹ mày bồi thường tiền khám răng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-03"},
  {"min": 4, "max": 4, "text": "Mày chôm lọ keo 502 của ông bô, đem ra dán chặt đôi tông lào của ông hàng xóm vào thềm xi măng. Sáng ổng ra đi làm, xỏ chân vào bước đi lật mẹ cả móng chân, chửi bới vang rền cả xóm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-04"},
  {"min": 4, "max": 4, "text": "Học được chiêu \"Thiên linh cái\" trên tivi, mày dùng dao lam cạo trọc đầu con búp bê Barbie của em gái rồi vẽ bùa lên mặt nó. Con em khóc cạn nước mắt, mày bị mẹ quất cho 5 lằn roi mây lươn lẹo.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-05"},
  {"min": 4, "max": 4, "text": "Mày tìm thấy lọ thuốc xổ của bà nội, tưởng là kẹo C vitamin nên đem ra cổng phân phát cho đám trẻ con trong xóm mỗi đứa 2 viên. Chiều đó, hệ thống cống ngầm của cả xóm hoạt động hết công suất, phụ huynh vác dao đi tìm mày.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-06"},
  {"min": 4, "max": 4, "text": "Mày thử nghiệm cảm giác mạnh bằng cách nhét một quả pháo diêm vào bãi cứt trâu còn tươi ngoài đồng rồi châm lửa. Cứt nổ tung tóe văng đầy mặt mũi áo quần mày, thối không ai dám đến gần trong bán kính 5 mét.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-07"},
  {"min": 4, "max": 4, "text": "Ở lớp, mày mở dịch vụ xăm hình dán bằng cách liếm ướt miếng decan rồi dập lên tay bọn con nít. Thu phí mỗi đứa 1 cái bánh bích quy. Trúng quả đậm, mày ăn bánh viêm cmn họng phải nghỉ học 3 ngày.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-08"},
  {"min": 4, "max": 4, "text": "Ngứa ngáy chân tay, mày vặt hết nụ hoa mười giờ của mẹ để làm \"thảo dược\" nấu canh đất. Mẹ đi làm về thấy chậu hoa trọc lóc, nổi trận lôi đình cấm mày xem siêu nhân 1 tháng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-09"},
  {"min": 4, "max": 4, "text": "Mày cãi nhau với thằng bạn hàng xóm, cay cú quá mày lén đái thẳng vào bình xăng con xe đạp điện của mẹ nó. Xe chết máy giữa đường, đến tận bây giờ bà ấy vẫn nghĩ do xăng bẩn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-10"},
  {"min": 4, "max": 4, "text": "Bắt được con rắn mối, mày nhét thẳng vào túi áo khoác của bà cô dạy múa. Đang tập múa, con rắn bò ra, bà cô ngất xỉu ngay tại chỗ. Mày bị kỉ luật đình chỉ học mẫu giáo 1 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-11"},
  {"min": 4, "max": 4, "text": "Lén lấy bật lửa gas của bố, mày châm thử xem râu con mèo có cháy không. Lửa bắt nhanh, con mèo hoảng loạn chạy quanh nhà làm xém luôn cả cái rèm cửa. Suýt thiêu rụi cả cái nhà, bố mày tống cổ mày ra khỏi cửa 2 tiếng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-12"},
  {"min": 4, "max": 4, "text": "Mày tưởng tượng mình là Tarzan, đu từ nóc tủ quần áo xuống giường nhưng xịt, đập mặt vào cạnh bàn gãy mẹ một cái răng cửa, mồm đầy máu. Cả nhà hú vía bế đi nha khoa viện trợ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-13"},
  {"min": 4, "max": 4, "text": "Đang ngồi ỉa thì hết giấy, mày tiện tay vớ luôn tờ hóa đơn tiền điện tháng này của mẹ để chùi đít. Cuối tháng bị cắt điện do chưa đóng tiền, mẹ lôi mày ra tổng sỉ vả 3 ngày 3 đêm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-14"},
  {"min": 4, "max": 4, "text": "Mày rủ đám bạn trong xóm chơi trò \"cướp nhà băng\". Vũ khí là súng nước pha nước mắm. Bắn trúng mắt thằng cu con ông tổ trưởng, cay xè. Nhà mày phải đi đền bù 2 giỏ trái cây nhập khẩu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-15"},
  {"min": 4, "max": 4, "text": "Thấy ông nội hút thuốc lào nhả khói ngầu quá, mày lén bốc một nhúm thuốc lào nhai thử. Tí thì sốc nhiệt sùi bọt mép, nôn thốc nôn tháo, ông nội phải vác mày đi trạm xá rửa ruột gấp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-16"},
  {"min": 4, "max": 4, "text": "Mày trốn ngủ trưa, lấy kéo cắt dây áo ngực phơi ngoài ban công của bà cô hàng xóm ế chồng. Bả phát hiện ra chửi xéo nhà mày suốt 1 tháng liền là \"đẻ con ra không biết dạy\".", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-17"},
  {"min": 4, "max": 4, "text": "Cô giáo hỏi ước mơ sau này của mày là gì. Trong khi bọn bạn bảo làm bác sĩ, kỹ sư, mày đứng lên dõng dạc: \"Cháu muốn làm giang hồ thu họ!\". Cô giáo sững sờ ghi ngay vào học bạ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-18"},
  {"min": 4, "max": 4, "text": "Mày bắt được một nắm ve sầu, nhét vào cặp lồng cơm của thằng béo nhất lớp. Trưa mở ra ve bay túa lúa, thằng béo khóc thét nôn hết bữa sáng. Mày lại có dịp thu họ phần cơm trưa của nó.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-19"},
  {"min": 4, "max": 4, "text": "Mày ị ra quần nhưng sĩ diện không dám nói cô giáo, cứ đóng bỉm cứt chạy nhong nhong cả buổi. Đến chiều cứt khô cứng lại dính chặt vào háng, mẹ mày phải lấy bùi nhùi sắt kì mãi mới sạch, đau thấu trời xanh.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-04-20"},
  {"min": 5, "max": 5, "text": "Đỉnh cao ẩm thực: Mày bắt được con thạch sùng đứt đuôi, nướng trên ngọn nến sinh nhật rồi chia cho thằng bạn thân mỗi đứa nửa con. Đêm đó cả hai thằng ôm bụng ỉa chảy ướt cả đệm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-01"},
  {"min": 5, "max": 5, "text": "Thấy bố để chai rượu ngâm bìm bịp trên bàn, mày tò mò vặn nắp tu một ngụm. Say lú người, mày cởi truồng chạy ra giữa ngõ múa quạt quẩy Vinahey. Cả xóm được bữa cười vỡ bụng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-02"},
  {"min": 5, "max": 5, "text": "Trong lễ tổng kết mẫu giáo, đến lượt mày lên nhận phiếu bé ngoan, mày bất ngờ giật mic của cô hiệu trưởng hét to: \"Địt mẹ cuộc đời!\". Cả hội trường im bặt, mày bị tước mẹ luôn tờ phiếu bé ngoan.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-03"},
  {"min": 5, "max": 5, "text": "Mày gạ thằng lớp phó trèo tường trốn học đi bắt nòng nọc. Bị kẹt dái trên hàng rào B40, mày khóc thét gọi cô bảo vệ ra giải cứu trong tình trạng trần truồng phần dưới. Nhục nhã ê chề.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-04"},
  {"min": 5, "max": 5, "text": "Nghe đồn nuốt hạt bưởi sẽ mọc cây trong bụng, mày lén nhét 5 hạt bưởi vào cốc nước cam của con em gái. Con em uống xong sợ khóc 3 ngày không dám ăn gì, mẹ mày quất cho mày một trận nát đít bằng móc áo.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-05"},
  {"min": 5, "max": 5, "text": "Mày bắt chước mấy anh dân tổ, lấy xe đạp ba bánh đổ dốc cầu thang ở chung cư. Xe lật nhào, mày gãy tay bó bột cmn 2 tháng, oai phong phết, đi học gái xúm lại kí tên lên bột.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-06"},
  {"min": 5, "max": 5, "text": "Mày lấy lọ sơn móng tay đỏ của mẹ tô màu lên đuôi con chó nhà. Con chó đi quanh xóm bị bạn bè bốn chân nhìn như người ngoài hành tinh, còn mày bị mẹ bắt tắm cho nó nguyên buổi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-07"},
  {"min": 5, "max": 5, "text": "Trổ tài ảo thuật, mày đút một đồng xu 5 nghìn vào lỗ mũi rồi đéo lấy ra được. Lại một lần nữa phải lên viện nhờ bác sĩ gắp. Bố mày thề từ nay đéo cho mày cầm tiền lẻ nữa.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-08"},
  {"min": 5, "max": 5, "text": "Đang ngồi xem hoạt hình, mày buồn đái nhưng tivi đang đoạn gay cấn. Thế là mày đái mẹ luôn vào cái vỏ chai C2 rồi để nguyên trên bàn. Tối ông bô đi làm về khát nước tu ực một phát... Thế chiến thứ 3 bùng nổ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-09"},
  {"min": 5, "max": 5, "text": "Tham gia đội bóng xóm, bị thằng bạn xoạc ngã. Đéo thèm đá bóng nữa, mày nhặt cục gạch ống đuổi phang thằng kia chạy khắp xóm. Bố nó ra can, mày lia thẳng viên gạch vào ống đồng bố nó. Đền tiền thuốc 1 củ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-10"},
  {"min": 5, "max": 5, "text": "Trưa hè không ngủ, mày lấy mút xốp đập nát ra làm \"tuyết nhân tạo\", rải khắp phòng ngủ rồi bật quạt số to nhất. Bố mẹ đi làm về nhìn phòng ngủ như bãi rác, bắt mày dọn 4 tiếng đồng hồ vừa dọn vừa khóc.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-11"},
  {"min": 5, "max": 5, "text": "Lén lấy cái quần lót ren đỏ của mẹ đội lên đầu làm mặt nạ Người Nhện, chạy loăng quăng ngoài ngõ. Gặp ai cũng văng tơ bằng nước bọt. Bà hàng xóm nhìn thấy bụm miệng cười, mẹ mày ra lôi cổ về đánh cho sưng đít.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-12"},
  {"min": 5, "max": 5, "text": "Mày học lỏm cách thắp hương, cắm 3 que nhang vào... bãi cứt chó trước cổng nhà để \"cúng cô hồn\". Gió thổi khói bay nghi ngút bốc mùi kinh tởm, cả xóm chửi nhà mày đéo biết nết dạy con.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-13"},
  {"min": 5, "max": 5, "text": "Chơi đuổi bắt, mày phi thân qua cái rãnh nước cống nhưng hụt chân, ngã tõm xuống bùn đen sì, hôi rình. Mày về nhà trong hình hài một con quái vật đầm lầy, mẹ mày đứng ngoài cửa dội 3 chậu nước rửa xe mới dám cho vào nhà.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-14"},
  {"min": 5, "max": 5, "text": "Ở lớp, mày mở \"sòng bạc\" ăn bim bim bằng tú lơ khơ tự vẽ. Bị cô giáo bắt quả tang, tịch thu tang vật. Mày khóc lóc ăn vạ lăn lộn ra sàn dọa cắn lưỡi tự tử, cô giáo sợ quá phải trả lại.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-15"},
  {"min": 5, "max": 5, "text": "Mày trộm dao cạo râu của bố, tự cạo trọc một đường từ trán ra sau gáy như kiểu tóc của Ro Béo. Sáng mai đi học cả trường cười hô hố, mày tự ái đấm nhau gãy mất cái răng hàm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-16"},
  {"min": 5, "max": 5, "text": "Bị con ong vò vẽ đốt một phát vào môi. Trông mày như được bơm môi filler bị lỗi, sưng chù vù. Thay vì ở nhà tĩnh dưỡng, mày ra ngõ chu mỏ dọa nạt lũ trẻ con trong xóm khóc thét.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-17"},
  {"min": 5, "max": 5, "text": "Mày lấy bùn trộn với cứt gà phết lên tường nhà hàng xóm để vẽ tranh bích họa \"Trận chiến Điện Biên Phủ\". Hàng xóm vác gậy sang tận nhà, bố mày phải bỏ tiền túi ra thuê thợ sơn lại nguyên bức tường.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-18"},
  {"min": 5, "max": 5, "text": "Mày tìm thấy chiếc găng tay cao su của bố trong ngăn kéo, tưởng là bóng bay đặc biệt bèn thổi căng rồi vẽ mặt cười lên. Bố tìm đồ mãi không thấy, còn mẹ cười ngặt nghẽo khi nhìn tác phẩm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-19"},
  {"min": 5, "max": 5, "text": "Chia tay tuổi mẫu giáo, mày ôm hôn thắm thiết con bé tổ trưởng rồi thầm thì vào tai nó: \"Lên lớp 1 tao sẽ làm đại ca trường, đợi tao thu họ lấy tiền mua nhẫn vàng cưới mày\". Con bé sợ tái mặt chạy méc cô.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-05-20"},
  {"min": 6, "max": 6, "text": "Ngày đầu vào lớp 1, mày khóc lóc bám chặt lấy chân cổng trường đéo chịu vào. Bố mày điên máu sút cho một phát bay thẳng vào sân. Mày nín bặt, lầm lũi đi tìm lớp với cái đít in nguyên dấu giày.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-01"},
  {"min": 6, "max": 6, "text": "Học viết bút máy, mày ngứa tay vẩy mực tím tứ tung ra bàn rồi bôi luôn lên mặt thằng ngồi cạnh. Thằng bé khóc ré lên, cô giáo phạt mày quỳ gối đội sách bục giảng 2 tiết liền.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-02"},
  {"min": 6, "max": 6, "text": "Giờ ra chơi, mày gạ bọn con trai thi đái vọt cần câu qua tường rào. Không may gió đổi chiều, nước đái bay ngược lại ướt hết áo trắng đồng phục. Trưa đó mày bốc mùi khai khẳm cả lớp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-03"},
  {"min": 6, "max": 6, "text": "Mất cục tẩy con chuột, mày cay cú thò tay sang cặp con bé lớp phó thó luôn cục tẩy thơm mùi dâu của nó. Bị phát hiện, mày già mồm cãi \"tẩy tao tự đẻ ra mùi này\", kết quả ăn 3 thước kẻ vào lòng bàn tay.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-04"},
  {"min": 6, "max": 6, "text": "Ngồi học buồn ỉa nhưng sợ cô giáo đéo dám xin ra ngoài. Mày rặn nhẹ ra quần rồi lấy cặp xách che lại. Cả lớp bịt mũi truy tìm thủ phạm, mày mồ hôi hột giả vờ ngửi ngửi đổ tội cho thằng bàn trên.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-05"},
  {"min": 6, "max": 6, "text": "Trộm được 5 nghìn của mẹ, mày ra cổng trường mua một nạm kẹo nổ nhét hết vào mồm. Kẹo nổ đôm đốp, mày há mồm ra khoe với gái, nước dãi lẫn kẹo xanh đỏ chảy thòng lòng nhìn như zombie.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-06"},
  {"min": 6, "max": 6, "text": "Học thuộc lòng đéo vào đầu, mày lén viết phao lên cánh tay. Lúc lên bảng mồ hôi ra nhòe mẹ hết chữ, mày đứng gãi đầu rồi đọc chế bài thơ \"O tròn như quả trứng gà, ô thời đội mũ, em thời ỉa đùn\". Zero điểm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-07"},
  {"min": 6, "max": 6, "text": "Mày bắt được con sâu đo, lén thả vào cổ áo bà cô chủ nhiệm lúc cô đang cúi xuống chấm bài. Cô giật mình hét toáng lên, cả lớp được bữa cười nắc nẻ, còn mày bị mời phụ huynh ngay hôm sau.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-08"},
  {"min": 6, "max": 6, "text": "Đang chơi đuổi bắt, mày cắm đầu chạy tông thẳng vào háng thầy giám thị. Thầy ngã khuỵu mặt tái mét, mày thì u một cục to tướng trên đầu, bị bế thẳng lên phòng y tế bôi dầu gió.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-09"},
  {"min": 6, "max": 6, "text": "Tham gia văn nghệ trường, mày được giao vai cây si đứng im. Ngứa háng quá, mày thò tay vào gãi sột soạt giữa lúc bài hát đang cao trào, khán giả ở dưới cười rần rần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-10"},
  {"min": 6, "max": 6, "text": "Đánh nhau với thằng lớp bên vì giành chỗ mua bim bim. Nó cào mặt mày rướm máu, mày cắn đứt đứt khuy áo của nó. Hai thằng bị lôi lên cột cờ đứng ôm nhau giảng hòa trước toàn trường.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-11"},
  {"min": 6, "max": 6, "text": "Giờ nghỉ trưa, mày lén chui gầm bàn buộc dây giày của 2 đứa bàn trên vào nhau. Lúc đánh trống đứng dậy, hai đứa ngã dập mặt, mày cười ha hả rồi bị nguyên cái chổi quét rác phang vào đầu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-12"},
  {"min": 6, "max": 6, "text": "Mày mót đái chạy vào nhà vệ sinh trường, thấy buồn nôn vì mùi đặc trưng. Mày quyết định đái luôn vào thùng rác góc hành lang. Bác lao công rình bắt được, xách tai mày giao cho hiệu trưởng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-13"},
  {"min": 6, "max": 6, "text": "Mày xé vở bài tập toán để gấp phi tiêu, phi trúng mắt thằng tổ trưởng. Nó khóc điếc tai, bố mẹ mày phải đền tiền đi khám mắt, tối về mày ăn combo lươn xào chổi lông gà.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-14"},
  {"min": 6, "max": 6, "text": "Đi học về không đi thẳng, mày la cà lội xuống mương bắt nòng nọc. Sụt hố bùn ướt sũng nửa người, vứt luôn đôi dép tổ ong dưới mương. Về nhà nói dối bị cướp chặn đường, bố mày vả cho không trượt phát nào.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-15"},
  {"min": 6, "max": 6, "text": "Thấy ông bảo vệ đánh trống trường ngầu quá, mày trộm dùi trống gõ loạn xạ lúc đang trong giờ học. Cả trường nhốn nháo tưởng báo động cháy, mày bị đình chỉ học 3 ngày.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-16"},
  {"min": 6, "max": 6, "text": "Mày phát minh ra trò lấy vỏ bút bi thổi giấy nhai. Bắn trúng gáy con lớp trưởng 5 phát liền. Nó quay xuống khóc òa méc cô. Cô giáo tịch thu \"vũ khí\", bắt dọn vệ sinh lớp 1 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-17"},
  {"min": 6, "max": 6, "text": "Trốn ngủ trưa, mày rủ mấy thằng trèo bệ xí để giả giọng ma trong hành lang. Bị cô giám thị phát hiện, cả bọn chạy toán loạn, đứa rơi dép, đứa đứt cả chun quần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-18"},
  {"min": 6, "max": 6, "text": "Bố mua cho cái cặp siêu nhân gao mới, mày tự hào vác đi khoe khắp lớp. Cuối giờ học bị thằng ất ơ nào lấy bút xóa vẽ thêm cái vòi voi vào háng siêu nhân, mày cay cú gầm rú tìm thủ phạm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-19"},
  {"min": 6, "max": 6, "text": "Hết tiền mua kem, mày gạ thằng bạn: \"Mày cho tao liếm 1 miếng, tao cho mày xem vết sẹo ở mông\". Giao dịch thành công, hai thằng lôi nhau ra góc cây phượng tụt quần kiểm chứng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-06-20"},
  {"min": 7, "max": 7, "text": "Lần đầu biết mùi quán Net, mày lấy cắp 10k tiền đi chợ của mẹ nạp vào chơi Half-Life. Bị mẹ cầm chổi đuổi từ quán net về nhà, chạy rơi cả dép, vừa chạy vừa gào thét xin tha.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-01"},
  {"min": 7, "max": 7, "text": "Tập đi xe đạp người lớn bằng cách luồn chân qua gióng ngang. Lao dốc đứt phanh, đâm thẳng vào gánh bún riêu của bà Tư đầu ngõ. Nước dùng nóng hổi hắt đầy người, mày suýt chín tái, nhà đền nguyên gánh bún.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-02"},
  {"min": 7, "max": 7, "text": "Chơi trò tạt lon ăn tiền lẻ, thua sạch túi. Cay cú, mày về thó cái nhẫn vàng tây của bà nội đem ra gạ gán nợ. May ông chú họ đi ngang tóm được, nếu không thì tàn đời.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-03"},
  {"min": 7, "max": 7, "text": "Đi bơi ở ao làng, mày bám vào con trâu đang tắm. Bị trâu vẩy đuôi quất một phát vào mặt, mày chìm nghỉm uống 3 ngụm nước ao đầy cứt trâu, lên bờ nôn ra toàn bùn xanh.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-04"},
  {"min": 7, "max": 7, "text": "Mày học đòi viết thư tình cho con bé lớp bên: \"Tớ yêu cậu như chó yêu xương\". Bị nó mang lên nộp cô giáo, cô đọc trước lớp, mày hận đàn bà từ năm 7 tuổi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-05"},
  {"min": 7, "max": 7, "text": "Lấy trộm bật lửa của bố để chơi trò nướng châu chấu. Nướng cháy mẹ đống rơm nhà hàng xóm. Bố mày phải vác xô nước chạy bở hơi tai đi dập lửa, tối đó nát đít với cái thắt lưng da.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-06"},
  {"min": 7, "max": 7, "text": "Tham gia băng đảng \"Sư tử nhí\" xóm dưới, vũ khí là súng bẹ chuối. Đi phục kích xóm trên bị tụi nó ném cứt trâu phản công. Mày dính nguyên quả vào mồm, giải nghệ giang hồ ngay lập tức.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-07"},
  {"min": 7, "max": 7, "text": "Trổ tài trèo cây bàng hái quả cho gái. Cành gãy, mày rơi tõm xuống đúng cái hố vôi đang tôi dở. May hố vôi nguội, nhưng quần áo dính vôi trắng xóa, về nhà mẹ đánh thêm cho rách quần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-08"},
  {"min": 7, "max": 7, "text": "Đeo kính cận giả giả vờ làm tri thức. Bị thằng bạn ngứa mắt đấm cho một phát gãy gọng kính, miểng nhựa đâm xước đuôi mắt. Vừa đau vừa nhục, vứt mẹ kính vào sọt rác.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-09"},
  {"min": 7, "max": 7, "text": "Mày gọt bút chì bằng dao lam nhưng lóng ngóng xẻo luôn một miếng da ngón tay. Máu tuôn xối xả, mày khóc thét ăn vạ bắt đền cô giáo vì \"tại cô bắt viết bài\".", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-10"},
  {"min": 7, "max": 7, "text": "Bực mình thằng ngồi trước cản tầm nhìn, mày dùng kéo cắt phăng một chỏm tóc sau gáy nó. Nó về méc mẹ, hôm sau mẹ nó mang kéo lên trường định cắt lại tóc mày.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-11"},
  {"min": 7, "max": 7, "text": "Ăn vụng miếng thịt lợn quay treo trên bếp, mỡ dính bóng loáng quanh mồm. Mẹ hỏi thì chối bay chối biến bảo \"tại con mèo cắn\", mày ăn ngay cái muôi xới cơm vào đầu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-12"},
  {"min": 7, "max": 7, "text": "Chơi pháo diêm (đập diêm sinh), mày chế quả pháo to đùng ném vào toilet trường lúc có đứa đang đi nặng. Tiếng nổ vang rền, đứa kia chạy ra kéo quần không kịp, mày bị đình chỉ học 1 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-13"},
  {"min": 7, "max": 7, "text": "Lén bắt một con cóc bỏ vào hộp bút của con bé điệu nhất lớp. Mở ra con cóc nhảy vồ vào mặt nó, nó ngất xỉu tại chỗ. Mày bị kỉ luật bêu tên trước cờ sáng thứ 2.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-14"},
  {"min": 7, "max": 7, "text": "Học được chiêu nhổ nước bọt có kiểm soát. Mày thi nhổ xa với lũ bạn ngoài ban công tầng 2, một bãi rớt trúng đầu ông thầy hiệu phó đi ngang. Cả lũ bỏ chạy tán loạn, mày rớt lại bị tóm gáy.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-15"},
  {"min": 7, "max": 7, "text": "Thấy xe máy chú hàng xóm cắm chìa khóa vứt đó, mày tò mò leo lên vặn ga. Xe chồm lên tông sập mẹ bức tường bao, mày bay vào đống cát phồng rộp cả người, nhà đền oan 5 củ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-16"},
  {"min": 7, "max": 7, "text": "Mày bắt dế mèn nhét vào tai để nghe nó gáy cho rõ. Con dế rúc sâu vào trong, ngứa điên cuồng, bác sĩ phải dùng kẹp nhỏ rỏ dầu mới lôi ra được một đống bầy nhầy.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-17"},
  {"min": 7, "max": 7, "text": "Đang xem cô dâu chú rể trao nhẫn, mày buồn rắm quá làm một phát to như sấm nổ. Không khí lãng mạn tan vỡ, cả rạp quay lại nhìn, mày giả vờ chỉ tay sang ông chú bên cạnh đổ tội.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-18"},
  {"min": 7, "max": 7, "text": "Nghĩ mình có năng lực siêu nhiên, mày dùng ô dù của mẹ làm dù nhảy từ nóc chuồng lợn xuống. Ô lật ngược, mày gãy tay trái, nằm viện 1 tuần, ỉa đái phải có người hầu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-19"},
  {"min": 7, "max": 7, "text": "Hết tiền mua kem, mày gạ thằng bạn đổi cả bộ sưu tập tem siêu nhân lấy một miếng kem. Cuộc giao dịch thành công, đến hôm sau mày hối hận vì mất hết tem.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-07-20"},
  {"min": 8, "max": 8, "text": "Đam mê MU Online, mày trộm nguyên con gà mái đẻ của bà nội đem ra chợ bán lấy 50k nạp thẻ reset. Bị phát hiện, mày quỳ gối xin lỗi trên đống vỏ chôm chôm 3 tiếng đồng hồ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-01"},
  {"min": 8, "max": 8, "text": "Hóa thân thành siêu trộm, mày lén lấy tiền trong ống heo của em gái bằng chiêu dùng nhíp gắp. Gắp hăng quá rách tờ 100k, mày nhét lại vào ống heo coi như không có chuyện gì.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-02"},
  {"min": 8, "max": 8, "text": "Chơi bắn bi ăn tiền rách quần lủng gối. Mày bị thằng lớn hơn bùng kèo cướp sạch bi, cay cú cầm gạch đuổi theo ném vỡ kính cửa sổ nhà người ta. Bố mày phải lên đền tiền thay.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-03"},
  {"min": 8, "max": 8, "text": "Thi học kì điểm kém, mày cạo sửa con 1 thành con 10 đỏ chót nhưng quên sửa điểm chữ. Bố phát hiện ra, mày bị ăn liên hoàn cước bằng móc quần áo sắt, khóc vang cả xóm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-04"},
  {"min": 8, "max": 8, "text": "Mày nhặt được đĩa VCD phim ma ngoài đường, lén mang về mở lúc bố mẹ vắng nhà. Đang xem thì kẹt đĩa, bố mẹ về bật tivi thấy ma nhảy xổ ra làm cả nhà hét tung nóc.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-05"},
  {"min": 8, "max": 8, "text": "Hợp tác với thằng bàn trên làm dịch vụ \"sao chép bài tập về nhà\", thu phí 2k/bài. Mở rộng quy mô quá lớn bị cô giáo tóm gọn đường dây. Đình chỉ học, bêu tên trước cờ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-06"},
  {"min": 8, "max": 8, "text": "Mày lấy thuốc lào của ông nội pha với nước để trị chấy trên đầu. Chấy đéo chết nhưng mày thì ngộ độc thuốc lào qua da, say lả người nôn mửa khắp giường.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-07"},
  {"min": 8, "max": 8, "text": "Thách đố ăn 5 quả ớt hiểm lấy 10k. Mày nhai xong khóc không ra nước mắt, mồm sưng như hai miếng dồi lợn, phải ngậm nước đá suốt 3 ngày không há mồm ăn cơm được.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-08"},
  {"min": 8, "max": 8, "text": "Đua xe đạp \"bốc đầu\" trước cổng trường. Bốc được 1 nhịp thì lộn cổ ra đằng sau, mài lưng xuống đường nhựa rách tanh bành áo sơ mi trắng, trầy nát da lưng tắm rát thấu xương.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-09"},
  {"min": 8, "max": 8, "text": "Mày lấy bút xóa vẽ hình con gián khổng lồ lên ghế của bà giáo khó tính. Bà giáo ngồi lên dính nguyên hình trắng toát vào áo, mày nơm nớp một tháng không dám hé răng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-10"},
  {"min": 8, "max": 8, "text": "Bị chó dại nhà hàng xóm đuổi, mày nhảy mẹ xuống cống nước thối ngập đến cổ để trốn. Mạng thì giữ được nhưng mùi thối ủ 3 ngày tắm 5 chai sữa tắm Lifebuoy vẫn không bay.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-11"},
  {"min": 8, "max": 8, "text": "Đang giờ chào cờ, buồn ỉa vã mồ hôi hột. Khớp háng lỏng lẻo thế đéo nào phọt luôn 1 bãi ra quần. Mày giả vờ ngất xỉu để được các bạn khênh xuống phòng y tế tẩu tán tang vật.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-12"},
  {"min": 8, "max": 8, "text": "Mày lén tháo sên xe đạp của thằng hay bắt nạt mày. Nó dắt xe cả cây số giữa trưa nắng khóc lóc. Mày đi ngang qua huýt sáo vẻ vang, hôm sau nó vác anh trai nó ra đón đường đấm mày sưng mắt.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-13"},
  {"min": 8, "max": 8, "text": "Bày trò đốt pháo sáng bằng quả bóng bàn cuộn giấy bạc. Ném vào lớp học mù mịt khói khét lẹt. Bảo vệ kích hoạt chuông báo cháy, mày nhục nhã đứng viết bản kiểm điểm 3 trang.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-14"},
  {"min": 8, "max": 8, "text": "Mày học lỏm võ Taekwondo, vung chân đá lộn xộn trong phòng khách làm vỡ chậu lan hồ điệp kỷ niệm của bố. Bố bắt mày quỳ đội chậu cây vỡ 4 tiếng đồng hồ cấm cãi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-15"},
  {"min": 8, "max": 8, "text": "Yêu thầm con bé lớp phó, mày nhét quả ổi cắn dở vào hộc bàn nó làm quà. Nó tưởng chuột cắn vứt mẹ vào thùng rác, mày tổn thương sâu sắc viết nhật ký chửi đàn bà vô tình.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-16"},
  {"min": 8, "max": 8, "text": "Trốn học bơi mương, quần áo để trên bờ bị tụi trâu bò ăn mẹ mất. Chiều muộn mày phải lấy lá chuối quấn quanh người đi bộ về làng như thổ dân, cả xóm ra xem đông như trẩy hội.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-17"},
  {"min": 8, "max": 8, "text": "Cắm tài khoản Gunbound ở tiệm net quên không thoát. Thằng ngồi sau lột sạch đồ quý, xóa luôn nhân vật. Mày khóc nguyên 1 tuần, thề không bao giờ bước chân vào quán net đó nữa.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-18"},
  {"min": 8, "max": 8, "text": "Mày cãi tay đôi với bà tổ trưởng dân phố: \"Bà lo chuyện bao đồng vừa thôi\". Bà ấy méc mẹ mày, bữa cơm tối của mày có thêm món \"vả mồm\", môi sưng vù ăn cơm nhạt nhẽo.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-19"},
  {"min": 8, "max": 8, "text": "Thấy con rắn nước bơi dưới ruộng, mày gan dạ lao xuống bắt để đi dọa gái. Không ngờ trượt chân ngã sấp mặt vào bãi phân trâu tươi. Rắn chạy mất, chỉ còn mày với hương đồng gió nội.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-08-20"},
  {"min": 9, "max": 9, "text": "Đỉnh cao hack cheat, mày chép phao thi vào mặt trong của cái compa. Vào phòng thi, mày mở compa ra lướt như James Bond, bị giám thị tóm tại trận xé bài cái rẹt. Điểm 0 tròn trĩnh.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-01"},
  {"min": 9, "max": 9, "text": "Thèm ăn trộm xoài nhà bà Tư, trèo qua tường bị con chó becgie rượt. Rách mảng quần ở mông, mày hốt hoảng bám cành xoài tụt xuống ngã trẹo chân, lê lết về nhà giả vờ ngã xe đạp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-02"},
  {"min": 9, "max": 9, "text": "Chôm tiền mẹ đi chơi điện tử thẻ ròng rã 1 tháng. Mẹ phát hiện quỹ thâm hụt, mày đổ thừa cho ông anh trai. Hai anh em bị trói vào cột nhà đánh chung cho chừa thói, từ đó thù nhau đéo nói chuyện.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-03"},
  {"min": 9, "max": 9, "text": "Sáng tác bài vè chửi thầy giám thị dài 10 câu truyền tay trong lớp. Thầy tóm được bản thảo có chữ ký của mày. Đình chỉ học 2 tuần, mời phụ huynh uống nước chè chửi cho xấp mặt.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-04"},
  {"min": 9, "max": 9, "text": "Học đòi hút thuốc lá Vinataba. Chui vào rơm hút, bị sặc khói ho rũ rượi rồi nôn thốc nôn tháo. Bố mày tưởng bị cảm gió bắt cạo gió đỏ lựng cả lưng, đau rát đéo dám kêu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-05"},
  {"min": 9, "max": 9, "text": "Mày rủ nguyên bang phái 5 thằng đi chặn đường thu họ 2k/đứa của bọn lớp dưới để lấy tiền chơi net. Bị phụ huynh tụi nó bắt quả tang, nguyên dàn 5 thằng đứng xếp hàng ăn bạt tai.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-06"},
  {"min": 9, "max": 9, "text": "Đam mê làm pháo nổ, mày cạo đầu diêm sinh nhét vào ruột van xe đạp rồi đập. Nổ to thật nhưng mảnh van văng trúng đùi chảy máu đầm đìa. Vào viện khâu 3 mũi, cạch mặt pháo diêm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-07"},
  {"min": 9, "max": 9, "text": "Tranh giành địa bàn chơi tạt lon, mày chửi thề gắt quá bị bà bán nước tát cho văng mẹ cái răng cửa sữa cuối cùng. Từ đó mày nói ngọng lứu lô, đéo tán được em gái nào nữa.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-08"},
  {"min": 9, "max": 9, "text": "Mày bóp keo 502 vào ổ khóa cửa phòng ông anh trai để trả thù. Ông anh đéo mở được cửa, cầm búa phá tung ổ khóa rồi đè mày ra tẩm quất nguyên 1 buổi chiều.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-09"},
  {"min": 9, "max": 9, "text": "Đang bơi sông thì thấy cức trôi, thay vì bơi né, mày hất nước đẩy bãi cứt về phía thằng bạn. Nó cay cú dìm mày uống 5 ngụm nước sông, mày lên bờ tiêu chảy cấp 1 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-10"},
  {"min": 9, "max": 9, "text": "Mày viết thư tình ẩn danh hẹn lớp trưởng ra sau gốc bàng, định làm trò bất ngờ. Đến nơi bọn mày tung bóng nước khiến bạn ướt sũng; cả lũ phải viết bản kiểm điểm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-11"},
  {"min": 9, "max": 9, "text": "Mày lén nhét con sâu róm vào cái mũ bảo hiểm của bố. Bố đội vào ngứa ngáy nổi mẩn đỏ khắp đầu. Bố tra khảo, mày chối không được đành nhận, bị cạo trọc đầu làm gương.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-12"},
  {"min": 9, "max": 9, "text": "Chơi trò nhảy cừu, thằng bạn đéo chịu cúi thấp, mày nhảy xoạc háng đập thẳng hai hòn dái vào lưng nó. Đau điếng người, mày nằm lăn lộn sân trường 15 phút, mồ hôi hột túa ra như tắm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-13"},
  {"min": 9, "max": 9, "text": "Rình xem trộm nhà hàng xóm cãi nhau li dị. Trượt chân rơi từ tường rào xuống đống gạch vụn xước sát hết mặt mũi. Hàng xóm tưởng mày nhảy lầu tự tử vội gọi cấp cứu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-14"},
  {"min": 9, "max": 9, "text": "Mày ăn vụng tiền đóng học phí để bao bạn bè đi ăn chè, ăn xiên bẩn. Cuối tháng cô đòi, mày giả chữ ký phụ huynh viết đơn xin nợ. Bị bóc phốt, mẹ mày tát mày bay từ nhà trước ra nhà sau.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-15"},
  {"min": 9, "max": 9, "text": "Bực mình vì con chó sủa đêm, mày ném hòn gạch to đùng. Đéo trúng chó mà trúng vỡ mẹ cửa kính nhà ông tổ trưởng. Đền 2 củ tiền kính, nhà mày cắt viện trợ ăn sáng của mày 3 tháng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-16"},
  {"min": 9, "max": 9, "text": "Mày mặc xịp đỏ của Superman ra ngõ múa võ. Gặp con chó điên nó lao ra đớp đúng vào mông. Chó dại nên mày phải đi tiêm rốn 7 mũi, khóc ré từng mũi tiêm đau điếng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-17"},
  {"min": 9, "max": 9, "text": "Thách đố uống 3 chai bò húc 1 lúc. Mày uống xong tăng động chạy nhảy khắp nhà, làm đổ bàn thờ Thần Tài của mẹ. Tro hương bay mù mịt, mày quỳ xin lỗi Thần Tài 2 tiếng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-18"},
  {"min": 9, "max": 9, "text": "Mày giả danh giọng người lớn gọi điện lên tổng đài xin quà tặng âm nhạc tặng cho em Hạnh lớp bên. Tổng đài viên chửi cho trận bảo \"ranh con vắt mũi chưa sạch\". Mày ngượng cúp máy vội.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-19"},
  {"min": 9, "max": 9, "text": "Mày ỉa bậy ra bãi đất trống bị bà nhặt ve chai bắt được. Quê quá, mày tụt quần chạy thục mạng về nhà, bỏ lại cái quần đùi siêu nhân bị bà kia thu làm chiến lợi phẩm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-09-20"},
  {"min": 10, "max": 10, "text": "Đỉnh cao giang hồ mạng Yahoo, mày lập nick “HoangTuBongDem_9x” đi làm quen con bé lớp bên. Không ngờ nick chat là ông anh trai nó cầm, hôm hẹn gặp mày chỉ muốn đào lỗ chui xuống đất.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-01"},
  {"min": 10, "max": 10, "text": "Sổ liên lạc đầy điểm 2,3, mày tự chế con dấu bằng củ khoai tây để đóng dấu trường và ký tên phụ huynh. Quá giả trân, giáo viên gọi điện báo thẳng cho mẹ. Đêm đó tiếng roi vút trong đêm không ngừng nghỉ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-02"},
  {"min": 10, "max": 10, "text": "Học đòi cá độ bóng đá quy mô tiểu học. Bắt ManU thua mẹ 50 nghìn. Đéo có tiền trả, bị bọn cầm cái lột mẹ đôi giày Bata trắng tinh, phải đi chân đất về nhà nói dối là bị chó tha.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-03"},
  {"min": 10, "max": 10, "text": "Mày chép lời bài \"Kiếp đỏ đen\" vào giấy nháp rớt trong lớp. Cô giáo nhặt được tưởng mày vướng vào tệ nạn cờ bạc thật, mời công an khu vực xuống trường giáo huấn 2 tiếng đồng hồ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-04"},
  {"min": 10, "max": 10, "text": "Mày cắt ảnh ca sĩ thần tượng từ báo rồi dán vào sách Toán để có động lực học. Cô giáo kiểm tra vở đột xuất tóm được, bắt mày lên bảng trình bày sự liên quan giữa đại số và ca nhạc.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-05"},
  {"min": 10, "max": 10, "text": "Tham gia hội đua xe đạp điện bốc đầu. Mày mượn xe mẹ bốc đầu rớt mẹ cái giỏ xe, gãy dè trước. Đem ra tiệm hàn lại tốn 200k, thâm hụt tiền ăn sáng suốt nửa năm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-06"},
  {"min": 10, "max": 10, "text": "Đi học võ Karate để tán gái. Lúc thi lên đai, mày sĩ diện đá vòng cầu hụt chân, đập háng xuống sàn trượt rút tê dái. Nằm cáng ra ngoài, mất sạch hình tượng giang hồ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-07"},
  {"min": 10, "max": 10, "text": "Chơi ném pháo đất với tụi xóm dưới. Mày trộn thêm cứt bò vào đất cho tăng sát thương. Ném trúng mồm thằng cầm đầu xóm kia, nó nôn tại chỗ. Bọn nó vác gậy lùa mày chạy 3 cây số đứt hơi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-08"},
  {"min": 10, "max": 10, "text": "Trộm thuốc nhuộm tóc của chị gái tự nhuộm một chỏm tóc vàng khè y hệt HKT. Sáng lên trường giám thị lôi tuột vào nhà vệ sinh lấy kéo xén cụt ngủn chỏm tóc, đầu mày lởm chởm như chó gặm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-09"},
  {"min": 10, "max": 10, "text": "Mày gạ lớp trưởng đi họp “băng hội bí mật” sau nhà xe rồi bị các cô lao công bắt gặp đúng lúc đang tập màn múa chào hỏi lố bịch. Từ đó cả trường gọi mày là “Đại ca nhà xe”.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-10"},
  {"min": 10, "max": 10, "text": "Bực mình ông thầy thể dục hay phạt hít đất, mày lấy xi măng nhét vào ổ khóa xe Dream của thầy. Thầy dắt xe cả buổi đéo nổ máy được, mày đứng trên tầng 2 cười thỏa mãn rồi bị check camera chạy đéo kịp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-11"},
  {"min": 10, "max": 10, "text": "Lên kế hoạch bỏ nhà đi bụi vì bị mắng. Gom được 50k với 2 gói mì tôm, mày ra ở gầm cầu xóm. Bị muỗi chích sưng mặt, nửa đêm sợ ma quá vác balo lết về gõ cửa xin lỗi mẹ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-12"},
  {"min": 10, "max": 10, "text": "Mày lén bỏ kẹo xổ số (kẹo kích thích tiêu hóa) vào chai nước của thằng lớp trưởng lúc nó đi vệ sinh. Trưa đó nó ỉa chảy cấp, suýt ỉa ra quần giữa lớp. Mày vừa hả hê vừa run vì sợ bị lộ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-13"},
  {"min": 10, "max": 10, "text": "Nhận làm đại ca bảo kê lớp, thu phí mỗi đứa 1k/ngày. Đụng độ băng lớp 5 bên cạnh, hai đại ca solo. Mày bị nó đấm cho chảy máu cam ướt hết áo sơ mi, về nộp mạng cho bố mẹ xài roi mây.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-14"},
  {"min": 10, "max": 10, "text": "Mày học lỏm cách tháo bugi xe máy của thợ sửa xe. Ra bãi xe trường tháo mẹ bugi xe của 3 cô giáo. Chiều đó bãi xe loạn cào cào, mày đem bán bugi được 30k đi ăn net.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-15"},
  {"min": 10, "max": 10, "text": "Thấy tổ ong vò vẽ trên cây me, mày cá cược 10k với đám bạn cầm đá ném. Trúng tổ ong, đàn ong lùa cả đám. Mày chạy chậm nhất dính 5 mũi chích, sưng húp 2 con mắt nhìn như Alien.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-16"},
  {"min": 10, "max": 10, "text": "Mày trộm dây chuyền bạc của em gái đem đi cắm tiệm đồ cũ lấy tiền mua kiếm nhựa chơi Trung Thu. Bị ông bô phát hiện, mày vác kiếm nhựa ra chống trả, ăn 1 chổi lông gà lươn lẹo 2 tháng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-17"},
  {"min": 10, "max": 10, "text": "Thách nhau ăn 5 bãi cứt mũi của chính mình lấy 20k. Mày nhắm mắt nhắm mũi nhai nuốt. Ăn xong lấy 20k đi mua xúc xích nướng, nhưng mồm mửa ra mùi hôi đéo nhai nổi đồ ăn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-18"},
  {"min": 10, "max": 10, "text": "Mày cãi tay đôi với cô giáo dạy Văn: \"Cô dạy thế này em thà đi bán vé số còn hơn!\". Cô sốc khóc tại lớp, hiệu trưởng đình chỉ học 1 tuần, lao động công ích quét sân trường.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-19"},
  {"min": 10, "max": 10, "text": "Chia tay tiểu học, mày vác cái loa kẹo kéo ra sân trường hát bài \"Kiếp ve sầu\" tặng tình yêu đơn phương. Đang hát thì loa hết pin rè rè rít lên, mày bị bảo vệ đuổi ra khỏi cổng nhục mặt giang hồ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-10-20"},
  {"min": 11, "max": 11, "text": "Tuổi dậy thì tới, mày phát hiện giọng nói bỗng vỡ như chiếc loa rè. Mày tưởng mình bị hỏng họng, đi khoe cả lớp và nhận ngay biệt danh “Loa kéo hết pin”.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-01"},
  {"min": 11, "max": 11, "text": "Thằng bạn rủ xem phim kinh dị lậu trên chiếc Nokia N70. Đang đến đoạn ma xuất hiện thì điện thoại của bố nó reo, hai thằng giật mình vứt máy vào xô nước.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-02"},
  {"min": 11, "max": 11, "text": "Tập tành xưng \"vợ - chồng\" với con bé lớp trưởng. Mày nặn đất sét thành hình trái tim tặng nó nhưng nhìn y chang bãi cứt, nó tởm quá vứt luôn vào sọt rác, block Yahoo mày luôn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-03"},
  {"min": 11, "max": 11, "text": "Mày chép trộm một bài rap chế về cô giáo vào vở Toán. Mẹ kiểm tra đọc thấy câu chửi bậy ngập trời, tối đó cả nhà mở phiên tòa kỷ luật chuyện học hành.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-04"},
  {"min": 11, "max": 11, "text": "Nghe giang hồ đồn lấy mủ mít bôi lên mép để râu mọc nhanh cho ngầu. Mày bôi xong dính chặt mẹ 2 mép vào nhau, phải lấy xăng thấm vào để chùi, rộp hết mồm mỏ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-05"},
  {"min": 11, "max": 11, "text": "Mày thách thằng bàn trên thi xem ai nhịn cười lâu hơn trong nhà vệ sinh. Thầy giám thị nghe tiếng cười rung tường, xông vào bắt quả tang hai đứa đang diễn hài.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-06"},
  {"min": 11, "max": 11, "text": "Mày bắt chước phim chưởng, vận nội công nhảy từ bậc thang số 5 xuống. Trượt chân đập háng vào góc cầu thang, thốn đến tận rốn, đi hai hàng suốt 1 tháng trời.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-07"},
  {"min": 11, "max": 11, "text": "Chơi Liên Minh Huyền Thoại ngoài quán net, mày gáy bẩn chửi thằng Riven team kia \"đồ con chó\". Hóa ra nó ngồi ngay máy đối diện, nó xách bàn phím sang vã mày gãy cmn 1 cái răng nanh.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-08"},
  {"min": 11, "max": 11, "text": "Đam mê ảo thuật, mày nuốt đồng xu 2k để làm trò biến mất trước mặt gái. Xu nghẹn ở cổ, mày khóc tím mặt, phải vào viện nội soi gắp ra, tốn 2 củ tiền viện phí của bố mẹ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-09"},
  {"min": 11, "max": 11, "text": "Tham gia thi chạy việt dã của trường, mày rút dây chun quần vì chật. Đang bứt tốc về đích thì quần đùi tụt mẹ xuống mắt cá chân, phơi nguyên cái sịp hình siêu nhân sứt chỉ. Cả trường cười bò.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-10"},
  {"min": 11, "max": 11, "text": "Lén lấy chai rượu ngâm bìm bịp của ông nội uống thử 1 tợp cho biết mùi đàn ông. Say lả lướt, mày nôn thốc nôn tháo ra thẳng bể cá cảnh, đàn cá La Hán 10 củ của ông nội ngửa bụng chết sạch.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-11"},
  {"min": 11, "max": 11, "text": "Giữa giờ học, bụng mày réo ọc ọc vì ăn sáng quá tay. Đúng lúc cô gọi lên giải Toán, mày bước lên với âm thanh như máy cày làm cả lớp cười bò.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-12"},
  {"min": 11, "max": 11, "text": "Chơi trò kẹp bút chì vào khe cửa rồi gọi đứa khác mở. Trúng ngay ông thầy dạy Hóa mở cửa, bút chì đâm thẳng vào mắt kính thầy vỡ tan tành. Mày bị đình chỉ học 3 ngày.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-13"},
  {"min": 11, "max": 11, "text": "Mày hack nick Audition của con bé điệu nhất xóm, lột sạch đồ Vcoin của nó đem bán lấy tiền mua thẻ Garena. Bị nó gọi anh trai ruột xăm trổ đến nhà túm cổ, nhà mày phải đền x3 lần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-14"},
  {"min": 11, "max": 11, "text": "Yêu đời nghêu ngao hát bài \"Tóc nâu môi trầm\" trong toilet, không biết thằng quỷ nào quay lại clip ném lên diễn đàn trường. Mày nổi tiếng bất đắc dĩ với biệt danh \"Thánh toilet\".", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-15"},
  {"min": 11, "max": 11, "text": "Thấy ông chú rể hút thuốc ngầu quá, mày lén mượn điếu Vina rít 1 hơi. Sặc khói ho rũ rượi, nước mắt mũi tèm lem, rớt mẹ điếu thuốc làm cháy thủng một lỗ trên áo khoác đồng phục.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-16"},
  {"min": 11, "max": 11, "text": "Mày cắm net thâu đêm, sáng hôm sau đi học ngủ gật, dãi chảy ròng ròng ướt đẫm quyển SGK Ngữ Văn. Cô giáo gọi dậy bắt đọc bài, mày đứng lên cầm quyển sách ướt nhẹp mồm còn hôi rình mùi mì tôm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-17"},
  {"min": 11, "max": 11, "text": "Bị mẹ sai đi mua mắm, mày ghé qua hàng điện tử xèng nướng sạch tiền. Về nhà đổ thừa bị rơi tiền, mẹ mày kiểm tra camera nhà hàng xóm thấy mày chui vào quán game. No đòn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-18"},
  {"min": 11, "max": 11, "text": "Mày học lỏm cách tự cắt tóc mái chéo kiểu HKT bằng kéo cắt giấy. Cắt lố tay lẹm mẹ một mảng to giữa trán, nhìn như bị chó cắn. Phải đội mũ lưỡi trai đi học ròng rã 3 tháng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-19"},
  {"min": 11, "max": 11, "text": "Mày tán gái bằng cách nhổ kẹo cao su đang nhai dở dính vào tóc nó để gây sự chú ý. Nó tức phát khóc, lấy kéo tự cắt cụt chỏm tóc rồi méc phụ huynh. Mày bị kỷ luật trước cờ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-11-20"},
  {"min": 12, "max": 12, "text": "Đặt status Yahoo bựa \"Trai xưa liều chết sa trường, trai nay liều chết trên giường mỹ nhân\". Bà dì lập nick ảo add mày vào đọc được, cap màn hình gửi cho mẹ. Mày bị tịch thu máy tính 6 tháng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-01"},
  {"min": 12, "max": 12, "text": "Trót dại lấy dao lam cạo thử lông tay lông chân cho mịn. Lúc mọc lại nó đen và cứng như lông heo rừng. Đi học mặc quần đùi, bọn bạn trêu là Người Vượn Tiến Hóa Lỗi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-02"},
  {"min": 12, "max": 12, "text": "Đam mê độ xe đạp điện, mày tháo acquy ra câu dây đèn led nhấp nháy. Đấu nhầm cực nổ cái đùng, cháy đen thui cả cái yên xe, mày sém lông mày, suýt thì lên bàn thờ ngắm gà khỏa thân.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-03"},
  {"min": 12, "max": 12, "text": "Có thằng lớp trên gạ đánh nhau, hẹn ra bãi đất trống sau giờ học. Mày rủ cả chục thằng anh em kết nghĩa đi cùng cho oai, ra đến nơi thấy bên nó cầm phóng lợn, cả team mày vứt dép cắm đầu chạy thục mạng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-04"},
  {"min": 12, "max": 12, "text": "Mày đặt mua “thuốc tăng trí nhớ siêu cấp” trên mạng, uống xong chỉ thấy đau bụng ba ngày. Đi học thì quên luôn mật khẩu điện thoại, IQ chẳng tăng nổi một điểm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-05"},
  {"min": 12, "max": 12, "text": "Thấy con xe SH của sếp bố để trước cửa, mày leo lên ngồi thử tạo dáng. Gạt chân chống chưa hết, xe đổ ầm xuống đất xước hết sơn, vỡ yếm. Mày bị bố treo ngược lên cành cây đánh bằng móc áo.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-06"},
  {"min": 12, "max": 12, "text": "Chơi game Đột Kích nạp tiền mua súng báu vật, hết mẹ nó tiền nộp học thêm. Đến ngày cô giáo gọi điện đòi học phí, mày chặn số cô giáo trên điện thoại của mẹ. Tháng sau cô đến tận nhà, toang!", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-07"},
  {"min": 12, "max": 12, "text": "Ghen tuông bọ xít với thằng lớp bên vì nó dám chở \"vợ\" mày đi học. Mày chặn đường ném bịch mắm tôm vào người nó, đéo ngờ ném trượt trúng ngay ông bác tổ trưởng dân phố. Đền tiền mệt nghỉ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-08"},
  {"min": 12, "max": 12, "text": "Đua đòi hút Shisha trong quán nước. Hút nhiệt tình quá ngộ độc khí CO, ngất xỉu tại chỗ. Tỉnh dậy thấy đang nằm truyền nước trong trạm xá, mẹ ngồi cạnh cầm sẵn cái chổi đót.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-09"},
  {"min": 12, "max": 12, "text": "Mày chế lời bài Quốc Ca thành bài chửi thầy Hiệu trưởng. Đang nghêu ngao hát trong nhà vệ sinh thì thầy bước ra từ buồng xí. Mày chết đứng, bị hạ hạnh kiểm Yếu cả năm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-10"},
  {"min": 12, "max": 12, "text": "Bực mình vì bị xếp ngồi cạnh con bé béo nhất lớp. Mày lén vẽ hình con lợn lên lưng áo nó. Nó khóc méc cô, mày bị phạt cõng nó chạy 3 vòng quanh sân trường, gãy mẹ cột sống.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-11"},
  {"min": 12, "max": 12, "text": "Cúp học đi bơi ở hồ Tây với đám bạn. Bị trộm cuỗm mất sạch quần áo trên bờ. Cả lũ phải bẻ lá sen che hạ bộ, đi bộ dọc đường Thanh Niên về nhà giữa hàng ngàn ánh mắt ngưỡng mộ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-12"},
  {"min": 12, "max": 12, "text": "Mày tỏ tình con hoa khôi bằng cách xếp 100 ngọn nến hình trái tim giữa sân trường. Gió thổi tạt lửa cháy cmn bồn hoa hồng kỷ niệm của trường. Kỷ luật, mời phụ huynh, đền tiền gấp đôi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-13"},
  {"min": 12, "max": 12, "text": "Nhận kèo vật tay ăn tiền với thằng to nhất xóm. Đang gồng đỏ mặt thì \"rắc\" một phát, gãy tay gập ngược ra sau. Mất 5 củ tiền bó bột, đéo được chơi game 3 tháng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-14"},
  {"min": 12, "max": 12, "text": "Mày lấy trộm chiếc áo khoác đắt tiền của chị gái đem lên lớp khoe. Cô giáo hỏi giấy tờ nguồn gốc, mày giải thích đó là “áo thể thao thế hệ mới”, cả lớp cười nắc nẻ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-15"},
  {"min": 12, "max": 12, "text": "Mày học lỏm trên mạng cách chế pháo bằng diêm. Nhồi nguyên 1 lọ penicillin đầy diêm sinh, châm lửa nổ toạc cả cái chậu hoa cúc nhà hàng xóm. Khói mù mịt, nhà bị chửi nguyên tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-16"},
  {"min": 12, "max": 12, "text": "Mày khoét lỗ nhỏ trên vách gỗ phòng trọ để ngó xem nhà bên có nuôi mèo không. Bị phát hiện đúng lúc đang dán mắt vào, hàng xóm xịt thẳng dầu gió vào khe khiến mày khóc ròng cả buổi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-17"},
  {"min": 12, "max": 12, "text": "Thách nhau ăn trộm chíp chíp trong siêu thị. Mày nhét một đống vào sịp, lúc đi qua cửa từ máy kêu ầm ĩ. Bảo vệ lục soát, lôi ra từ trong háng mày một nạm kẹo bọc dính dính hôi hôi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-18"},
  {"min": 12, "max": 12, "text": "Mày trốn học thêm đi chơi bi-a. Bị mẹ phục kích, cầm cơ bi-a lùa đánh quanh bàn. Mày chạy quanh hét \"Mẹ tha cho con, con trót dại\". Cả quán được xem phim hài miễn phí.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-19"},
  {"min": 12, "max": 12, "text": "Hợp tác với thằng bạn mở dịch vụ \"Cho chép phao thi Giữa Kỳ\". Mày viết phao chữ siêu nhỏ bán 10k/bản. Bị giám thị tóm 1 đường dây 5 đứa. Mày là chủ mưu, ăn cái đình chỉ học 2 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-12-20"},
  {"min": 13, "max": 13, "text": "Tham gia bang phái \"Thiên Địa Hội\" trên Facebook, mày set ava ảnh thằng giang hồ mạng cởi trần xăm trổ. Đi học bị bọn lớp trên ghét cái thái độ, chặn đường lột mẹ áo đồng phục vứt xuống mương.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-01"},
  {"min": 13, "max": 13, "text": "Đam mê làm Youtuber, mày quay clip \"Thử thách ăn cứt mũi của chó\". Đăng lên bị chửi rủa sấp mặt, lượng dislike kỷ lục. Tới trường đéo ai dám ngồi gần vì mồm mày hôi như bãi rác.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-02"},
  {"min": 13, "max": 13, "text": "Chơi net nợ chủ quán 500k đéo có tiền trả. Chủ quán tịch thu cái xe đạp điện Xmen của mày. Về nhà báo mất cắp, bố mày báo công an khu vực, công an check cam ra tận tiệm net lôi cổ mày về tẩm quất.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-03"},
  {"min": 13, "max": 13, "text": "Cãi nhau với người yêu trên mạng, mày chụp ảnh mặt mếu máo với lời tuyên bố “nghỉ chơi cả thế giới”. Cả lớp tưởng mày bỏ học thật, kéo nhau tới nhà hỏi thăm, mày quê muốn độn thổ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-04"},
  {"min": 13, "max": 13, "text": "Học cách châm thuốc lá bằng 1 tay bật lửa Zippo. Múa múa thế đéo nào rớt lửa thẳng vào đũng quần. Cháy xém lông háng, mày hốt hoảng lấy tay đập phành phạch giữa quán cafe, gái nhìn tởm lợm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-05"},
  {"min": 13, "max": 13, "text": "Mày lập nick giả danh con gái để lừa thẻ game của bọn con trai lớp bên. Lừa được ba trăm nghìn thì bị phát hiện, bọn nó kéo đến tận nhà đòi tiền và đưa cả ảnh chat lên nhóm lớp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-06"},
  {"min": 13, "max": 13, "text": "Chơi lớn lấy sơn xịt chữ \"A.Y.E\" (Anh Yêu Em) to tướng lên cổng nhà con bé hàng xóm. Bố nó là dân xã hội, vác dao sang tận nhà bắt mày lấy bàn chải đánh răng chà sạch nguyên cái cổng thép.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-07"},
  {"min": 13, "max": 13, "text": "Mày lấy thuốc nhuộm đen của mẹ đổ vào hộp sữa gội đầu của ông anh trai. Lão gội xong đầu đen thui cả da đầu, rửa đéo ra. Lão tóm mày đè ra cạo trọc đầu bằng tông đơ cùn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-08"},
  {"min": 13, "max": 13, "text": "Đăng status chửi xiên xỏ ông thầy Hóa: \"Dạy như bòi, thích ra vẻ\". Quên mẹ chưa block thầy. Thầy cap màn hình gửi vào group phụ huynh, mày ăn trận đòn nát chổi, bảo lưu hạnh kiểm Yếu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-09"},
  {"min": 13, "max": 13, "text": "Thách kẹo dẻo cay nhất thế giới. Ăn xong ruột gan lộn tùng phèo, đau dạ dày cấp cứu lúc 2h sáng. Bác sĩ rửa dạ dày bằng ống thông qua mũi, thấu tận trời xanh, cạch mặt đồ cay đến già.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-10"},
  {"min": 13, "max": 13, "text": "Mày bày đặt đi quán karaoke với các anh lớn. Uống nước ngọt quá nhiều, lại nhảy múa không ngừng nên nôn ra sàn, bị bảo vệ bế ra vỉa hè và cả nhóm cấm mày làm DJ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-11"},
  {"min": 13, "max": 13, "text": "Lên kế hoạch đánh ghen giùm con bạn thân. Mày xông vào tát nhầm cmn con em gái của thằng tra nam. Bị gia đình nó khởi kiện tội cố ý gây thương tích, đền 10 củ tiền hòa giải.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-12"},
  {"min": 13, "max": 13, "text": "Thấy điện thoại bố hớ hênh, lén mò vào mục tin nhắn thấy bố đang nhắn tin tình cảm với cô đồng nghiệp. Mày tống tiền bố 500k để giữ mồm. Bố đưa 500k xong tối lôi mày ra đánh đòn vì tội \"hỗn láo\".", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-13"},
  {"min": 13, "max": 13, "text": "Mày chôm con gà chọi 5 triệu của chú ruột đem đi đá độ. Gà chưa đá đã bị con gà khác mổ mù 1 mắt. Chú mày xót gà, phạt mày quỳ úp mặt vào tường đội chậu nước nguyên ngày Chủ Nhật.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-14"},
  {"min": 13, "max": 13, "text": "Nhét băng vệ sinh của chị gái vào giày để đi êm chân theo mẹo trên Tiktok. Giờ Thể dục chạy nhảy hăng quá, cái băng nó lòi ra ngoài lủng lẳng. Đám con gái chỉ trỏ cười ngất, mày chui mẹ xuống lỗ nẻ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-15"},
  {"min": 13, "max": 13, "text": "Bực mình con chó nhà hàng xóm ị trước cổng, mày đặt biển “CẤM PHÓNG UẾ” viết tay đầy lỗi chính tả. Chủ chó đọc được cười lăn, còn mày phải dọn bãi chiến trường.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-16"},
  {"min": 13, "max": 13, "text": "Mày lén tráo bài kiểm tra Toán 8 điểm của thằng bạn thành bài 3 điểm của mình. Tráo nhầm mẹ bài của con lớp trưởng. Nó khóc um lên, giám thị check vân tay (đùa, check nét chữ), mày bị đình chỉ 1 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-17"},
  {"min": 13, "max": 13, "text": "Trèo tường trốn học đi chơi net, quần kẹt vào hàng rào thép gai rách toạc từ háng xuống gấu quần. Mày đéo dám đi lại, đành ngồi thu lu ở góc tường đến tối mịt mới dám lẻn về.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-18"},
  {"min": 13, "max": 13, "text": "Mày thả rắn lục đồ chơi vào túi xách bà giáo dạy Sinh học. Bả thò tay vào lấy đồ, sờ thấy trơn trơn, hét ầm lên rồi tăng xông ngất xỉu. Mày bị cả trường ném đá, gia đình bồi thường tiền thuốc.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-19"},
  {"min": 13, "max": 13, "text": "Mày gạ đua xe đạp điện bốc đầu ăn tiền. Xe mày yếu, lúc bốc lên bị gãy luôn cổ phốt, bánh trước văng ra ngoài, mặt mày cày xuống đường nhựa mòn mẹ cái mũi, khâu 10 mũi trên mặt.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-13-20"},
  {"min": 14, "max": 14, "text": "Áp lực thi vào cấp 3, mày xé mẹ sách Toán để nướng cá mực nhậu với đám bạn. Bố phát hiện, bắt mày chép tay lại toàn bộ quyển SGK Toán tập 2 trong 3 ngày, tay mày sưng vù, đéo cầm nổi đũa.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-01"},
  {"min": 14, "max": 14, "text": "Mày lập page \"Hội những người ghét cô Hiệu trưởng\" thu hút 500 thành viên. Công an mạng dò ra IP nhà mày. Ban giám hiệu mời phụ huynh, suýt thì cấm thi chuyển cấp, phải quỳ lạy xin lỗi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-02"},
  {"min": 14, "max": 14, "text": "Thích con bé khối dưới, mày dùng keo 502 dán hàng trăm bông hồng nhựa lên yên xe máy điện của nó. Keo dính chặt hỏng cmn yên xe bọc da xịn. Mày đền 2 củ tiền bọc yên, gái cạch mặt.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-03"},
  {"min": 14, "max": 14, "text": "Mày lén bỏ thuốc xổ vào bình nước lọc của phòng giáo viên. Sáng hôm sau 5 thầy cô xin nghỉ ốm đột xuất vì tiêu chảy. Vụ án chưa tìm ra thủ phạm nhưng mày sống trong sợ hãi tột độ, mất ăn mất ngủ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-04"},
  {"min": 14, "max": 14, "text": "Cắm con xe đạp Asama được 300k để đập đồ trong Võ Lâm Truyền Kỳ. Thất bại, vỡ nợ, mày phải đi bốc vác cát thuê cho công trường ngoài xóm 1 tháng trời để chuộc lại xe trước khi bố phát hiện.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-05"},
  {"min": 14, "max": 14, "text": "Mày học lỏm trên mạng cách xăm hình bằng kim khâu và mực Cửu Long. Tự xăm chữ \"Hận\" lên bắp tay, sưng tấy mưng mủ nhiễm trùng nặng. Vào viện bác sĩ phải nạo thịt thối, để lại cái sẹo lồi như con đỉa.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-06"},
  {"min": 14, "max": 14, "text": "Đang thi học kì, mày giấu phao trong tất. Cúi xuống lôi ra thì giám thị tưởng mày buộc lại dây giày quá lâu, đi tới kiểm tra và phát hiện cả tập tài liệu bí mật.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-07"},
  {"min": 14, "max": 14, "text": "Tổ chức tiệc chia tay lớp 9, mày lén pha rượu Vodka vào bình trà đá. Cả lớp lớp 9 say bí tỉ, múa quạt, chửi thề ầm ĩ. Cô chủ nhiệm tức điên, hủy luôn buổi chụp ảnh kỷ yếu, mày bị lớp tẩy chay.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-08"},
  {"min": 14, "max": 14, "text": "Đú đởn xỏ khuyên tai, mày nhờ thằng bạn lấy kim băng đâm xuyên qua dái tai. Đau chảy nước mắt, máu chảy ròng ròng, 3 ngày sau nhiễm trùng mưng mủ to như quả nho, phải đi tiểu phẫu gỡ bỏ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-09"},
  {"min": 14, "max": 14, "text": "Mày cãi nhau với mẹ, xách balo ra nhà nghỉ ngủ 1 đêm cho bõ tức. Nửa đêm bị công an phường kiểm tra hành chính, đéo có CCCD, bị gọi phụ huynh lên bảo lãnh lúc 3h sáng trong nhục nhã.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-10"},
  {"min": 14, "max": 14, "text": "Tranh nhau tán một con bé với đại ca xóm bên. Nó hẹn mày ra đê giải quyết. Mày sợ quá đéo dám ra, trốn trong tủ quần áo. Nó kéo người đến tận nhà ném vỡ kính sổ, bố mày phải ra đàm phán đền tiền.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-11"},
  {"min": 14, "max": 14, "text": "Mày lén trộm đề thi thử môn Hóa trên bàn cô giáo, photocopy bán cho cả khối với giá 50k/bản. Cô giáo phát hiện đề bị lộ, đổi đề mới cứng. Cả khối rớt đài, bọn mua đề xúm lại đòi đánh mày bầm dập.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-12"},
  {"min": 14, "max": 14, "text": "Thách nhau ăn bọ xít nướng. Mày ăn trúng con chưa chín kỹ, mồm sưng phù, cổ họng dị ứng nghẹt thở, đi cấp cứu thở oxy mất 2 ngày. Xém thì ăn chuối ngắm gà khỏa thân tuổi 14.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-13"},
  {"min": 14, "max": 14, "text": "Mày dùng Photoshop ghép mặt thầy giám thị vào poster siêu anh hùng rồi gửi nhóm kín chế nhạo. Có đứa mách thầy, mày bị bắt làm bản xin lỗi dài hơn một bài văn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-14"},
  {"min": 14, "max": 14, "text": "Lén lấy xe máy Cub 50 của ông nội đi chở gái dạo quanh bờ hồ. Đang vênh váo thì đâm thẳng vào đít xe rác. Hai đứa ngã lộn nhào vào đống rác thối hoắc, gái bỏ về bằng taxi block số luôn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-15"},
  {"min": 14, "max": 14, "text": "Mày bắt dế chọi, nhét vào cặp sách đem lên lớp bán. Dế xổng ra kêu rỉ rả suốt giờ Toán. Cô giáo bắt cả lớp im lặng tìm, mày bị lôi lên đứng góc lớp ngậm nguyên con dế sống trong mồm 5 phút.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-16"},
  {"min": 14, "max": 14, "text": "Bực mình vì mẹ thu điện thoại ôn thi, mày lén đổ nước mắm vào chai dầu gội đầu của mẹ. Mẹ gội xong hôi rình, lôi mày ra phang bằng cán chổi gãy làm đôi, bắt mày hít đất 100 cái.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-17"},
  {"min": 14, "max": 14, "text": "Thấy con xe phân khối lớn dựng vỉa hè, mày chạy lại tạo dáng chụp ảnh sống ảo. Vô tình gạt trúng cần số, xe đang nổ máy chồm lên tông vào cột điện. Đền 20 củ, bố mẹ phải bán mẹ bộ bàn ghế gỗ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-18"},
  {"min": 14, "max": 14, "text": "Mày tỏ tình qua đài phát thanh trường lúc giờ ra chơi: \"Anh yêu em nhiều như chó yêu xương\". Trưởng ban phát thanh báo cáo BGH, mày bị cấm túc và lao động dọn toilet 2 tuần.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-19"},
  {"min": 14, "max": 14, "text": "Mày nhét quả pháo nổ vào bãi cứt trâu ngoài đồng rồi châm ngòi. Khẩu độ tính sai, pháo nổ văng cức trâu thẳng vào mồm và mặt mày. Mày khóc thét đi tắm sông nửa ngày vẫn đéo hết mùi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-14-20"},
  {"min": 15, "max": 15, "text": "Ngày đầu nhập học lớp 10, mày vuốt keo vuốt sáp đi con Wave Alpha tháo yếm cho ngầu. Bị mấy thằng lớp 12 ngứa mắt chặn cổng trường rút chìa khóa vứt mẹ xuống cống. Mày dắt bộ 3 cây số về nhà.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-01"},
  {"min": 15, "max": 15, "text": "Tỏ tình con hoa khôi khối 10 bằng cách hát rap bài \"Thu Cuối\" giữa sân trường. Đang hát thì vấp cục đá ngã dập môi, đứt dây thanh quản. Gái che miệng cười khinh bỉ, mày trở thành trò hề toàn khối.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-02"},
  {"min": 15, "max": 15, "text": "Học quân sự, mày lén lấy quả bóng tập rồi ném vào sân thể dục đang đông người. Cả sân nhốn nháo tưởng có bóng lạ rơi từ trời, mày bị kỷ luật và mời phụ huynh.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-03"},
  {"min": 15, "max": 15, "text": "Tập tành chơi Tài Xỉu online. Ăn được 5 củ, sĩ diện bao cả lớp đi uống trà sữa. Hôm sau thua ngược 10 củ, mày phải đi trộm sắt vụn nhà hàng xóm bán trả nợ, bị chó đuổi rách cả quần sịp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-04"},
  {"min": 15, "max": 15, "text": "Nghe lời xúi dại, mày xăm quả \"cá chép hóa rồng\" nửa lưng nhưng thợ xăm tay nghề non, xăm ra con cá trê quấn khúc củi. Đi tắm biển đéo dám cởi áo vì nhục.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-05"},
  {"min": 15, "max": 15, "text": "Đú đởn hút Pod trong nhà vệ sinh, nhả khói hình chữ O ngầu đét. Trúng ngay lúc thầy Hiệu trưởng đi đái, khói bay thẳng vào mặt thầy. Mày bị tịch thu Pod, bêu tên trước cờ, hạnh kiểm Yếu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-06"},
  {"min": 15, "max": 15, "text": "Đánh ghen hội đồng giùm con bạn thân. Mày hăng máu xông vào túm tóc, ai ngờ túm nhầm mẹ bà cô dạy Hóa đang đi ngang qua. Mày ăn 3 cái tát nổ đom đóm mắt, bị đày xuống cuối lớp ngồi 3 năm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-07"},
  {"min": 15, "max": 15, "text": "Trốn tiết Thể dục đi chơi bi-a. Bị ông bô phục kích cầm gậy bi-a lùa từ quán chạy về tận nhà. Cả xóm ra xem mày bị lột quần đánh đòn giữa sân, tiếng khóc vang vọng một vùng quê.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-08"},
  {"min": 15, "max": 15, "text": "Yêu qua mạng với một \"em gái\" 2k trên Audition. Nạp cho nó 2 triệu tiền thẻ. Ngày hẹn gặp mặt ngoài quán nước, hóa ra là một thằng đực rựa 90kg đầy lông lá. Mày xách dép chạy đéo dám ngoảnh lại.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-09"},
  {"min": 15, "max": 15, "text": "Tham gia đội bóng trường, mày đòi sút quả penalty quyết định. Chạy đà như Ronaldo, sút một phát trượt quả bóng, sút gãy mẹ ngón chân cái. Đội nhà thua, mày bó bột 1 tháng, bị cả đội tế sống.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-10"},
  {"min": 15, "max": 15, "text": "Lén mang rượu Vodka pha Sting vào lớp uống dịp sinh nhật. Say bét nhè, mày trèo lên bàn giáo viên quẩy bài \"Múa quạt\". Cô giáo vào lớp xỉu ngang, mày ẵm ngay quả kỷ luật cảnh cáo.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-11"},
  {"min": 15, "max": 15, "text": "Mày cắm con xe đạp điện của mẹ lấy 2 củ đi đập đồ Võ Lâm. Đập xịt, đéo có tiền chuộc. Mày nói dối bị cướp kề dao vào cổ cướp xe. Công an vào cuộc điều tra ra sự thật, mày bị bố vả gãy mẹ 1 cái răng nanh.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-12"},
  {"min": 15, "max": 15, "text": "Thách đố ăn 10 quả ớt hiểm lấy 500k. Mày ăn xong nóng phừng phừng, uống nhầm chai cồn y tế. Đi rửa ruột cấp cứu lúc nửa đêm, suýt thì ngỏm củ tỏi ở tuổi trăng tròn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-13"},
  {"min": 15, "max": 15, "text": "Lập group anti thầy Giám thị trên Facebook. Quên đéo set private, thầy vào nằm vùng cap lại hết tin nhắn chửi bới. Mày và 5 thằng nữa bị gọi lên phòng BGH quỳ gối viết bản kiểm điểm 5 trang.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-14"},
  {"min": 15, "max": 15, "text": "Mày đi sinh nhật bạn, uống nhầm ly nước có pha thuốc \"kích thích\". Phê pha đi dạo, ôm nhầm cái cột điện tưởng người yêu, hì hục hôn hít. Có đứa quay clip tung lên confession trường, nhục để đâu cho hết.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-15"},
  {"min": 15, "max": 15, "text": "Bực mình con lớp trưởng hay méc, mày lấy keo 502 dán mẹ cái ghế vào mông nó. Nó đứng lên rách toạc cả quần. Nó khóc bù lu bù loa, mày phải đền cái quần mới, gia đình đến tận nơi xin lỗi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-16"},
  {"min": 15, "max": 15, "text": "Mày xé trộm sổ đầu bài để phi tang vết nhơ trốn tiết. Bị BGH phát hiện bắt đền quyển sổ mới và gọi phụ huynh. Bố mày tức quá cạo trọc nửa đầu mày, đi học như sư cọ đi lạc.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-17"},
  {"min": 15, "max": 15, "text": "Trèo tường trốn học đi chơi nét, mày trượt chân mắc kẹt trên hàng rào. Bảo vệ phải gọi thang giải cứu, cả trường có dịp chụp ảnh mày lủng lẳng như chiếc áo phơi.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-18"},
  {"min": 15, "max": 15, "text": "Mày học lỏm trên mạng cách chế pháo bằng diêm và ống nhựa. Đốt thử ở sân nhà, nổ cái đoàng, bay mẹ mảnh chai văng vào vỡ kính nhà hàng xóm. Đền 3 củ tiền kính, ăn đòn nát đít.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-19"},
  {"min": 15, "max": 15, "text": "Mày cược 50 nghìn rằng có thể ăn hết bốn bát mì cay trong một phút. Vừa ăn bát thứ hai đã sặc nước, mất sạch phong độ và cả tiền cược, bị người ta gọi là “vua mì cay hụt”.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-15-20"},
  {"min": 16, "max": 16, "text": "Đòi bố mua Exciter 150 để đi tán gái không được, mày dỗi bỏ nhà đi bụi. Ra quán net nằm 3 ngày 3 đêm hôi như cú, hết tiền phải mò về xin lỗi rớt nước mắt. Bố cho mày đi con xe Cub 50 ghẻ lở.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-01"},
  {"min": 16, "max": 16, "text": "Cầm con Wave Alpha của nhà đi bốc đầu trên đường đê. Lên đầu được 5 giây thì lật ngửa, mài lưng xuống đường nhựa dài 10 mét. Nát bươm lưng, xước hết mặt mũi, xe nát bét. Bố mẹ khóc thét trả tiền viện.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-02"},
  {"min": 16, "max": 16, "text": "Yêu say đắm con bé lớp 11A. Phát hiện nó cắm sừng mày quen thằng đi SH. Mày rủ anh em ra cổng trường chặn đánh, ai ngờ thằng kia gọi 5 thằng xăm trổ cầm tuýp sắt ra. Mày quỳ xuống xin lỗi xưng \"cháu\" luôn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-03"},
  {"min": 16, "max": 16, "text": "Tập tành ghi lô đề cho cả lớp ăn hoa hồng. Bị thầu đề quỵt tiền trúng, cả lớp quay sang đòi mày. Ôm cục nợ 10 củ, mày phải cắm thẻ học sinh, cắm điện thoại, về ăn cắp tiền của mẹ bù vào.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-04"},
  {"min": 16, "max": 16, "text": "Đi dã ngoại cùng trường, mày rủ người yêu vào rừng ngồi tâm sự. Đang khoe giọng hát thì hai đứa bị đàn ong bám theo, phải chạy về khu cắm trại trong bộ dạng tóc tai bù xù.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-05"},
  {"min": 16, "max": 16, "text": "Mày quay phao thi môn Lịch Sử siêu đẳng, giấu trong đũng quần. Giám thị nam phát hiện bắt thò tay vào tự moi ra. Mày lóng ngóng moi cả quần sịp ra ngoài, cả phòng thi cười nghiêng ngả.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-06"},
  {"min": 16, "max": 16, "text": "Mày cúp học đi gặp tình yêu mạng ở quán nước xa lắc. Đúng lúc định tỏ tình thì công an khu vực kiểm tra quán vì mất xe. Phụ huynh bị gọi tới đón, mày ôm cặp xin lỗi suốt đường về.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-07"},
  {"min": 16, "max": 16, "text": "Đi bar sinh nhật bạn, sĩ diện gọi 2 bình shisha với tháp bia. Lúc tính tiền hết 5 củ, cả bọn đéo đứa nào có tiền. Mày phải ở lại rửa bát, dọn dọn WC quán bar 1 tuần trừ nợ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-08"},
  {"min": 16, "max": 16, "text": "Đú trend vuốt tóc kiểu \"khá bảnh\", mày đi học bị ông giám thị ngứa mắt lôi ra cột cờ lấy kéo xén cụt. Từ dân chơi 104 chuyển sang phu phen bốc vác trong 1 nốt nhạc.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-09"},
  {"min": 16, "max": 16, "text": "Mày mua lén thuốc ngủ định cho ông bô uống để tối trốn đi quẩy. Bỏ nhầm mẹ vào cốc nước của bà nội. Bà nội ngủ li bì 2 ngày đéo tỉnh, cả nhà đưa đi viện cấp cứu tưởng đột quỵ. Mày ăn đòn thập tử nhất sinh.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-10"},
  {"min": 16, "max": 16, "text": "Cay cú thằng lớp trưởng, mày lấy xô nước tiểu từ nhà vệ sinh đổ ụp từ tầng 2 xuống đầu nó lúc ra chơi. Nó kiện lên BGH, mày bị đuổi học 1 tháng, chuyển trường trong sự ô nhục.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-11"},
  {"min": 16, "max": 16, "text": "Hợp tác với đường dây thi hộ, mày nhận thi thuê môn Toán. Bị giám thị tóm tại trận vì mặt mày đéo giống mặt trong thẻ học sinh (thằng kia mặt rỗ, mày mặt nhẵn). Cả hai đứa bị đình chỉ thi 1 năm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-12"},
  {"min": 16, "max": 16, "text": "Nhậu nhẹt cùng đám bạn, mày cố thể hiện tửu lượng rồi lăn ra ngủ giữa sân đình. Sáng hôm sau các cụ đi tập thể dục nhìn thấy mày ôm chai nước lọc, chụp ảnh tung lên nhóm xóm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-13"},
  {"min": 16, "max": 16, "text": "Mày lén trộm dây chuyền vàng của mẹ đi bán lấy tiền nạp game. Bị chủ tiệm vàng nghi ngờ báo công an. Công an gõ cửa tận nhà, mẹ mày sốc lên máu, mày lãnh đủ 10 roi điện của ông bô.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-14"},
  {"min": 16, "max": 16, "text": "Học đòi xịt nước hoa cho thơm để tán gái. Mày xịt nửa lọ Chanel pha-ke 50k mua trên Shopee. Mùi hôi như bọ xít cộng thêm mùi viêm cánh, gái ngửi thấy buồn nôn vác vú chạy.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-15"},
  {"min": 16, "max": 16, "text": "Mày trèo tường ký túc xá để trốn buổi lao động công ích. Trượt chân rơi xuống mương nước thối, được cứu lên thì bị phạt cọ nhà vệ sinh một tháng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-16"},
  {"min": 16, "max": 16, "text": "Tham gia giải đá bóng ăn tiền. Mày xoạc bóng ác ý làm gãy chân thằng tiền đạo đội bạn. Bọn nó quây lại đấm mày gãy 2 cái xương sườn. Nhập viện nằm 1 tháng, đền tiền thuốc cho cả 2 bên.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-17"},
  {"min": 16, "max": 16, "text": "Mày chế ảnh chế thầy Hiệu phó ghép vào MV \"Quăng tao cái boong\". Lượt view tăng chóng mặt. Ban giám hiệu mời công an mạng vào cuộc, mày bị bế lên phường uống nước chè, phạt 7.5 triệu tội bôi nhọ BGH.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-18"},
  {"min": 16, "max": 16, "text": "Trốn mẹ đem sổ đỏ đi cầm đồ vay 20 củ định \"khởi nghiệp\" bán pod. Bị thằng bạn chí cốt cuỗm sạch tiền rồi trốn mất tăm. Mày quỳ lạy bố mẹ cứu nét, nhà phải bán mẹ mảnh đất phần trăm để chuộc sổ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-19"},
  {"min": 16, "max": 16, "text": "Mày rủ đám bạn về nhà nhậu nhẹt lúc bố mẹ đi vắng. Tụi nó nôn mửa khắp sô pha, nôn cả vào bể cá Koi của bố. Cá chết ngửa bụng, sô pha bốc mùi. Bố về mày bị sút tung đít bay ra khỏi nhà.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-16-20"},
  {"min": 17, "max": 17, "text": "Mày và người yêu tưởng có một tin lớn khiến cả hai sợ xanh mặt. Sau khi bình tĩnh tìm hiểu hóa ra chỉ là báo động nhầm, mày vẫn thề từ nay bớt hành động bốc đồng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-01"},
  {"min": 17, "max": 17, "text": "Đam mê bóng bánh, bắt trận chung kết C1 xịt. Nợ chủ bóng 50 củ. Bọn giang hồ tạt sơn đỏ, mắm tôm đầy cổng nhà mày. Bố mẹ mày phải bán rẻ con SH để trả nợ cho thằng con báo thủ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-02"},
  {"min": 17, "max": 17, "text": "Mày mạo danh bố viết đơn xin thôi học để đi làm giang hồ mạng. Mở kênh Tiktok livestream chửi thề kiếm view. Bị giang hồ thật tới tận nơi bạt tai, bắt quỳ xin lỗi trên sóng livestream. Khóa kênh vĩnh viễn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-03"},
  {"min": 17, "max": 17, "text": "Mày uống rượu say cãi tay đôi với CSGT lúc bị bắt vì không đội mũ bảo hiểm. Dám vung tay đấm trượt ông dân phòng. Bị còng tay bế lên đồn, ăn combo tội chống người thi hành công vụ, bố mẹ bảo lãnh mất 10 củ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-04"},
  {"min": 17, "max": 17, "text": "Cắm thẻ học sinh vay app online hai triệu mua giày xịn. Không trả được, app gửi ảnh chế bêu tên mày khắp nhóm họ hàng. Mày phải thú nhận với gia đình và đi làm thêm trả nợ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-05"},
  {"min": 17, "max": 17, "text": "Mày đi bar cùng các anh lớn lần đầu, bị lừa mua gói dịch vụ VIP giá cắt cổ. Một tuần sau nhìn hóa đơn mày chỉ biết ôm đầu xin mẹ tiền trả nợ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-06"},
  {"min": 17, "max": 17, "text": "Lập team cướp giật mũ bảo hiểm trên đường cho oai. Giật trúng mũ của ông cảnh sát hình sự mặc thường phục. Bị đạp ngã xe, còng tay tại chỗ, xém vào trại giáo dưỡng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-07"},
  {"min": 17, "max": 17, "text": "Mày bắt cá 2 tay, yêu cùng lúc 2 em ở 2 lớp khác nhau. Tụi nó phát hiện ra, lập mưu hẹn mày ra công viên. Hai đứa xúm lại xé rách áo, vả lật mặt mày giữa bàn dân thiên hạ. Giang hồ mạng cap lại làm meme.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-08"},
  {"min": 17, "max": 17, "text": "Đỉnh cao lười học, mày thuê thằng sinh viên Bách Khoa làm tiểu luận tốt nghiệp giùm với giá 2 củ. Thằng đó copy paste 100% trên mạng. Bị BGH quét phần mềm đạo văn, đánh trượt tốt nghiệp thẳng tay.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-09"},
  {"min": 17, "max": 17, "text": "Mày nhậu nhẹt tưng bừng, sĩ diện leo lên cột điện cao thế để chứng tỏ độ liều. Điện giật phóng cái xẹt, mày văng xuống đất cháy đen thui một mảng đùi. Nằm viện bỏng quốc gia 3 tháng, suýt hẹo.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-10"},
  {"min": 17, "max": 17, "text": "Bức xúc vì bị cô giáo bắt viết kiểm điểm, mày lén chọc thủng 2 lốp xe SH của cô. Camera trường soi nét căng mặt mày. Đền 2 cái lốp Michelin 3 củ, ăn đuổi học 1 tháng sát kì thi chuyển cấp.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-11"},
  {"min": 17, "max": 17, "text": "Gạ gẫm con gái ông chủ quán bia. Ông chủ quán phát hiện, sai 3 thằng bưng bê xách mã tấu rượt mày quanh làng. Mày vứt cả xe đạp điện lội qua ao bèo hôi thối trốn đến tận 3h sáng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-12"},
  {"min": 17, "max": 17, "text": "Mày học lỏm cách tự chế bom mù (smoke bomb) định quăng vào lớp quậy. Trộn sai tỷ lệ, nó nổ phốc một cái cháy mẹ luôn mái tóc lãng tử bồng bềnh. Mày mang quả đầu nham nhở đi học suốt 2 tháng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-13"},
  {"min": 17, "max": 17, "text": "Mày chôm thẻ ATM của ông bô đi rút 10 củ dẫn gái đi ăn Hadilao. Bố nhận được SMS trừ tiền, khóa thẻ báo công an. Tối về ăn combo móc áo nhôm tẩm quất hằn nguyên lươn đỏ khắp lưng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-14"},
  {"min": 17, "max": 17, "text": "Tham gia phượt Tam Đảo bằng xe máy. Vượt đèo cua gắt, mày xòe xe rớt mẹ xuống rãnh nước, gãy xương quai xanh. Nằm liệt giường 2 tháng, lỡ mất kỳ thi học kỳ, phải học lại 1 năm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-15"},
  {"min": 17, "max": 17, "text": "Mày lập sòng xóc đĩa trong nhà vệ sinh nam. Thầy hiệu trưởng đi vi hành tóm gọn cả ổ. Tịch thu 500k tiền mặt, mày là cái nên bị tước tư cách thi đua, xém bị lưu ban.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-16"},
  {"min": 17, "max": 17, "text": "Mày sĩ diện mua nhẫn vàng giả (vàng mỹ ký) tặng bạn gái nhân ngày 14/2. Nó đeo bị dị ứng mẩn đỏ, đi tiệm vàng kiểm tra biết là đồ đểu. Nó vứt nhẫn vào mặt mày chửi \"Đồ rẻ rách\", chia tay vĩnh viễn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-17"},
  {"min": 17, "max": 17, "text": "Trốn học đi chơi ở khu nghỉ dưỡng với nhóm bạn, mày nhảy lên giường biểu diễn nhào lộn. Giường gãy rầm một cái, lễ tân đòi một triệu tiền sửa. Mày gọi bố mẹ đến giải cứu trong nhục nhã.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-18"},
  {"min": 17, "max": 17, "text": "Mày giấu người yêu việc đã tiêu sạch tiền tiết kiệm để mua đồ game. Cô ấy phát hiện, hai bên cãi nhau to. Mày phải đi làm thêm cả tháng mới đền bù được số tiền đã mượn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-19"},
  {"min": 17, "max": 17, "text": "Mày gáy bẩn trên rank Liên Quân, cho địa chỉ thách nó đến. Nó rủ 10 thằng đến tận nhà mày đập cửa ầm ĩ. Bố mày phải vác rựa ra đứng canh cửa. Nhục nhã, mày trốn biệt trong phòng đéo dám ra đường.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-17-20"},
  {"min": 18, "max": 18, "text": "Kỳ thi Đại học định mệnh. Mày ngủ quên mẹ mất môn thi Toán. Tỉnh dậy lúc 9h sáng, trời đất quay cuồng. Trượt thẳng cẳng, ở nhà chăn vịt 1 năm, ăn bám bố mẹ nhục như chó.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-01"},
  {"min": 18, "max": 18, "text": "Liên hoan chia tay lớp 12, mày uống say bét nhè tỏ tình với cô giáo chủ nhiệm: \"Cô ơi em yêu cô\". Cả lớp quay clip đăng Tik Tok, cô giáo đỏ mặt tát mày 1 cái cháy má.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-02"},
  {"min": 18, "max": 18, "text": "Rớt Đại học, bố mẹ đuổi thẳng cổ ra khỏi nhà. Mày xách vali ra phòng trọ ở, đi làm phục vụ quán nhậu. Bị khách say rượu chửi rủa, ném ly bia vào đầu khâu 3 mũi. Thấm thía mùi đời.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-03"},
  {"min": 18, "max": 18, "text": "Mày nhận lời rủ rê đi làm đa cấp lô hội. Lừa cả họ hàng, vay mượn 50 củ nạp vào hệ thống để lên hạng \"Giám đốc Kim Cương\". Tháng sau hệ thống sập, mày trốn chui trốn lủi vì bị cả họ từ mặt đòi nợ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-04"},
  {"min": 18, "max": 18, "text": "Thi đỗ vớt vào trường Đại học dân lập rẻ rách. Lên thành phố nhập học, ngày đầu tiên bị lừa đảo đa cấp mất mẹ 5 củ tiền đóng trọ. Phải ngủ gầm cầu 2 đêm mới dám gọi điện khóc với mẹ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-05"},
  {"min": 18, "max": 18, "text": "Liên hoan nhậu chia tay, mày phóng xe máy 100km/h tông thẳng vào dải phân cách. Văng xa 10 mét, gãy 1 chân 1 tay. Thay vì đi học đại học, mày ngồi xe lăn 6 tháng cắn răng chịu đau.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-06"},
  {"min": 18, "max": 18, "text": "Mày chơi coin (Cryto) theo mấy anh thầy trên mạng. Cắm sổ đỏ của bà ngoại vay 100 củ All-in vào đồng Shitcoin. 1 đêm nó chia 100 lần, tài sản còn đúng 1 củ. Mày đứng trên cầu Long Biên suy nghĩ về cuộc đời.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-07"},
  {"min": 18, "max": 18, "text": "Đi khám sức khỏe NVQS. Mày cố tình xăm kín lưng hù bác sĩ để trốn nghĩa vụ. Bác sĩ cười khẩy đánh trúng tuyển. Mày ngậm ngùi cắt tóc 3 phân vác balo đi bộ đội 2 năm, để lại con người yêu ở nhà theo thằng khác.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-08"},
  {"min": 18, "max": 18, "text": "Đỉnh cao simp lỏ, mày làm thêm bưng bê 3 tháng gom được 10 củ mua iPhone tặng gái đỗ Đại học. Gái nhận quà xong nhắn tin: \"Mình chia tay đi, khoảng cách xa quá\". Mày khóc thét dưới trời mưa to.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-09"},
  {"min": 18, "max": 18, "text": "Mày cắm bằng tốt nghiệp cấp 3 vay nặng lãi 20 củ đi chơi tài xỉu. Lãi mẹ đẻ lãi con lên 50 củ. Xã hội đen đến nhà dọa cắt gân. Bố mày phải vay ngân hàng trả nợ, rồi đuổi mày ra khỏi hộ khẩu.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-10"},
  {"min": 18, "max": 18, "text": "Bực mình BGH, ngày bế giảng mày lén trộn thuốc xổ vào nồi chè liên hoan toàn trường. 500 học sinh tranh nhau đi ỉa, BGH gọi công an điều tra. Mày lọt lưới nhưng sống trong dằn vặt 10 năm sau.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-11"},
  {"min": 18, "max": 18, "text": "Đi làm shipper giao hàng mùa hè, mày trót ăn vụng hộp cơm của khách. Khách xem camera phốt lên mạng. App khóa tài khoản vĩnh viễn, mày mất bát cơm, bị giang hồ mạng bêu rếu là \"thằng đói ăn\".", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-12"},
  {"min": 18, "max": 18, "text": "Tham gia thi Rap Việt mùa 1. Mày on mic hát bài diss Bố mẹ tao. Trấn Thành lắc đầu, Binz chê gắt. Lên sóng truyền hình thành trò hề quốc dân, ra đường phải đeo khẩu trang 1 năm trời.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-13"},
  {"min": 18, "max": 18, "text": "Mày nhận lời dọn phòng trọ cho chị chủ nhà để được giảm tiền thuê. Chồng chị ấy về thấy hai người bừa bộn đồ đạc, tưởng nhà bị trộm và gọi cả xóm đến. Mày giải thích đến khản cổ.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-14"},
  {"min": 18, "max": 18, "text": "Khởi nghiệp bán giày fake online. Chạy ads nợ Facebook 20 củ. Hàng bị quản lý thị trường ập vào bắt sạch vì đéo có hóa đơn. Mày ôm cục nợ 50 củ năm 18 tuổi, đời tăm tối.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-15"},
  {"min": 18, "max": 18, "text": "Mày dẫn người yêu về nhà chơi lúc bố mẹ đi vắng, bày tiệc bất ngờ nhưng làm đổ cả bàn bánh. Bà nội lên phòng tìm dầu gió thấy phòng như bãi chiến trường, phải gọi cả nhà lên dọn.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-16"},
  {"min": 18, "max": 18, "text": "Thi bằng lái xe máy lần đầu. Mày vặn ga mạnh quá tông mẹ húc đổ rào chắn, phi thẳng xe vào ban giám khảo. Rớt thẳng cẳng, đền tiền sửa rào, bị cấm thi 1 năm.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-17"},
  {"min": 18, "max": 18, "text": "Rủ anh em đi xăm kỉ niệm tình bạn \"Mãi mãi anh em\". Xăm xong thợ báo 15 củ, cả bọn đéo có tiền trả. Bị chủ quán bắt để lại xe máy và điện thoại xịn. Về nhà bị bố táng cho ù tai.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-18"},
  {"min": 18, "max": 18, "text": "Mày cãi nhau với gia đình, quyết định xách balo đi phượt Tây Bắc một mình. Giữa đèo thủng lốp, trời tối mù, bị hai thằng dân tộc lột sạch ví và điện thoại. Mày đi bộ 20 cây số xin ăn mới về được đồng bằng.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-19"},
  {"min": 18, "max": 18, "text": "Ngày ra trường, mày nhậu say xỉn, chặn đường đấm luôn thằng cờ đỏ ngày xưa hay bắt lỗi mày. Đập nó gãy mũi, nhà nó báo công an. Mày nhận tiền án cố ý gây thương tích tuổi 18, đóng cửa tương lai.", "type": "event", "weight": 1, "ageSpecific": true, "ageEventId": "new-age-18-20"},
];
